INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Fazlul Haque$b$, DATE '1938-06-30', DATE '2023-11-16', $b$Mohammad Fazlul Haque (Bengali: ম. ফজলুল হক, Fojlul Hoq) (30 June 1938 – 16 November 2023) was a Bangladeshi judge who served as the acting chief adviser of Bangladesh for one day before the appointment of the Fakhruddin Ahmed ministry in January 2007.

