INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Dino Shafeek$b$, DATE '1930-03-21', DATE '1984-03-10', $b$Dino Shafeek (born Gholam D. Shafeek, 21 March 1930 – 10 March 1984) was a British Bangladeshi actor specialising in comedy roles. Born and raised in Dhaka, he moved to the United Kingdom in 1958 and appeared in several sitcoms during the 1970s and early 1980s. He is best remembered for playing the part of Chai Wallah Muhammed in the BBC sitcom It Ain't Half Hot Mum and the role of Ali Nadim in ITV sitcom Mind Your Language.

Source: Wikipedia — https://en.wikipedia.org/wiki/Dino_Shafeek$b$, 'en', NULL, $b$Film actor, Television actor, Comedian, Actor$b$, $b$Dhaka$b$, $b$London$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Salma Sobhan$b$, DATE '1937-08-11', DATE '2003-12-30', $b$Salma Sobhan (née Rasheda Akhtar Banu; 11 August 1937 – 30 December 2003) was a Bangladeshi lawyer, academic and human rights activist. She became the first woman barrister in Pakistan in 1959. A member of the law faculty of the University of Dhaka, she was a co-founder of Ain-O-Salish Kendra (ASK), a national human rights watchdog. She was also a key figure at the Bangladesh Institute of Law and International Affairs (BILIA).

Source: Wikipedia — https://en.wikipedia.org/wiki/Salma_Sobhan$b$, 'en', NULL, $b$Barrister$b$, $b$London$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sheikh Kamal$b$, DATE '1949-08-05', DATE '1975-08-15', $b$Sheikh Kamal (5 August 1949 – 15 August 1975) was a Bangladeshi politician, athlete, and military officer. He was the eldest son of Sheikh Mujibur Rahman, the founding president of Bangladesh, and the younger brother of Sheikh Hasina, who would later become prime minister of Bangladesh. He was the founder of Abahani Limited Dhaka. He is considered as a youth icon in Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sheikh_Kamal$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sheikh-Kamal-222-1167x660.jpg?width=640$b$, $b$Politician$b$, $b$Gopalganj$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Siddika Kabir$b$, DATE '1931-05-07', DATE '2012-01-31', $b$Siddika Kabir (7 May 1931 – 31 January 2012) was a Bangladeshi nutritionist, academic, cookbook author, and cooking show television host. A professor, Kabir hosted, and guest starred in television shows featuring Bangladeshi cuisine, including Siddiqua Kabir's Recipe on NTV Bangla.

Source: Wikipedia — https://en.wikipedia.org/wiki/Siddika_Kabir$b$, 'en', NULL, $b$Nutritionist, Television presenter, Author$b$, $b$Dhaka$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sumita Devi$b$, DATE '1936-02-02', DATE '2004-01-06', $b$Sumita Devi (Bengali: সুমিতা দেবী) (born Hena Bhattacharya) also known as Nilufar Begum (February 2, 1936 - January 6, 2004) was a Bangladeshi actress. In 45 years of her career, she acted in around 200 films and 150 radio and television dramas. She was an artist at the Swadhin Bangla Betar Kendra in 1971.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sumita_Devi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Kancher%20Deyal.jpg?width=640$b$, $b$Actor$b$, $b$Dhaka$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nurjahan Begum$b$, DATE '1925-06-04', DATE '2016-05-23', $b$Nurjahan Begum (4 June 1925 – 23 May 2016) was the first female journalist in Bangladesh and a trailblazer for female journalists in South Asia. Begum was awarded Ekushey Padak in 2011 by the Government of Bangladesh. She served as the editor of Begum magazine.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nurjahan_Begum$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/NurjahanBegum.jpg?width=640$b$, $b$Journalist$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mahbubey Alam$b$, DATE '1949-02-17', DATE '2020-09-27', $b$Mahbubey Alam (17 February 1949 – 27 September 2020) was a Bangladeshi politician, designated senior counsel, and Attorney General for Bangladesh. He was appointed attorney general on 13 January 2009. He was a senior advocate at the Supreme Court of Bangladesh. He had served earlier as additional attorney general from 15 November 1998 to 4 October 2001.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mahbubey_Alam$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mahbube%20alam%202017.jpg?width=640$b$, $b$Lawyer$b$, $b$Munshiganj District$b$, $b$Combined Military Hospital$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Tridev Roy$b$, DATE '1933-05-14', DATE '2012-09-17', $b$Raja Tridiv Roy (Urdu: تری دیو رائے; Chakma: 𑄖𑄳𑄢𑄨𑄘𑄨𑄝𑄴 𑄢𑄧𑄠𑄴) sometimes spelled Tridev Roy, (14 May 1933 – 17 September 2012) was a Pakistani Buddhist politician, diplomat and writer who was Minister of Minorities Affairs & Tourism in the Zulfikar Ali Bhutto cabinet. He was also the 50th Raja of the Chakma tribe in the Chittagong Hill Tracts region of present-day Bangladesh from 2 May 1953, until his abdication in 1971 following the Bangladesh Liberation War. He chose to remain a Pakistani when Bangladesh achieved independence in 1971. He became known as a writer, diplomat, Buddhist religious leader and politician in Pakistan. 

Between 1981 and 1995, he served as Ambassador of Pakistan to Argentina with concurrent accreditation in Chile, Uruguay, Peru and Ecuador. He was also a Minister-For-Life within the Pakistani government. Tridev Roy died in September 2012.

Source: Wikipedia — https://en.wikipedia.org/wiki/Tridev_Roy$b$, 'en', NULL, $b$Diplomat, Politician, Writer$b$, $b$Rajbari District$b$, $b$Islamabad$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mashiur Rahman$b$, DATE '1924-07-09', DATE '1979-03-12', $b$Mashiur Rahman (9 July 1924 – 12 March 1979), also known as Jadu Mia (Bengali: জাদু মিয়া, lit. 'Man of Magic'), was a senior minister, with the rank and status of prime minister, in charge of the Ministry of Railways, Roads and Highways of Bangladesh from 29 June 1978 to 12 March 1979.

He was the founder of the Bangladesh Nationalist Party; the whole process of transition to multi-party democracy was his brainchild. He named the party, and the election symbol was given to the party from his party, the National Awami Party (Bhashani) (NAP).

He also made the formal Declaration of Independence of Bangladesh from his party NAP (there were two major political parties in the then East Pakistan, one National Awami Party, NAP and Awami League), on the 23 March 1971, when Sheikh Mujib was still negotiating for the premiership of Pakistan with the military junta of Pakistan, not giving the formal declaration despite people's determination for a free, independent country.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mashiur_Rahman_(politician%2C_born_1924)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Moshiur%20Rahman%20%28politician%2C%20born%201924%29.jpg?width=640$b$, $b$Politician$b$, $b$Rangpur District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khandaker Abdullah Jahangir$b$, DATE '1958-11-05', DATE '2016-05-11', $b$Khandaker Abu Nasr Muhammad Abdullah Jahangir (Arabic: أبو نصر محمد عبد الله جهانغير بن خوندكار أنور الزمان, Bengali: খোন্দকার আবু নসর মুহাম্মদ আব্দুল্লাহ জাহাঙ্গীর; (1 February 1958 – 11 May 2016), or Abdullah Jahangir, was a Bangladeshi Islamic scholar, professor, television presenter and author. He participated in public lectures across Bangladesh and during his time as Professor of Al-Hadith in Islamic Studies at the Islamic University, Bangladesh, 12 of his students received PhD and 30 achieved MPhi. He has authored many Islamic books which have received great acclaim in the South East Asian Region.

Source: Wikipedia — https://en.wikipedia.org/wiki/Khandaker_Abdullah_Jahangir$b$, 'en', NULL, $b$Researcher, Professor, Writer$b$, $b$Jhenaidah District$b$, $b$Magura District$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Humaira Himu$b$, DATE '1985-11-23', DATE '2023-11-02', $b$Humaira Nusrat Himu, better known as Humaira Himu (Bengali: হুমায়রা হিমু; 23 November 1985 – 2 November 2023) was a Bangladeshi television and film actress. She made her film debut in Amar Bondhu Rashed in 2011. She had appeared in TV dramas like DB, Sanghat, Chairman Bari, Batighor, and Shonena She Shonena.

Source: Wikipedia — https://en.wikipedia.org/wiki/Humaira_Himu$b$, 'en', NULL, $b$Actor$b$, $b$Lakshmipur District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mohammed Nasim$b$, DATE '1948-04-02', DATE '2020-06-13', $b$Mohammed Nasim (2 April 1948 – 13 June 2020) was a Bangladesh Awami League politician who served as Bangladesh's minister of home affairs and minister of health and family welfare during 1999–2001 and 2014–2019, respectively. He was a six-term Jatiya Sangsad member representing the Sirajganj-1 and Sirajganj-2 constituencies. He was a presidium member of Awami League and the spokesperson of the 14-party alliance.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mohammed_Nasim$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mohammed%20Nasim%20in%20New%20Delhi%20on%20April%2013%2C%202016.jpg?width=640$b$, $b$Politician$b$, $b$Sirajganj District$b$, $b$Shamoly$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Zinnatunnessa Talukdar$b$, NULL, DATE '2023-10-29', $b$Zinatun Nesa Talukdar (1947 – 29 October 2023) was a Bangladesh Awami League politician who was the state Minister of Primary and Mass Education. She also served as the State Minister of Women and Children Affairs. She was one of the three female ministers out of 43 cabinet ministers in the First Sheikh Hasina Cabinet during 1996–2001.

Talukdar was awarded by the Government of Bangladesh a Begum Rokeya Padak in 2018.

Source: Wikipedia — https://en.wikipedia.org/wiki/Zinnatunnessa_Talukdar$b$, 'en', NULL, $b$Politician$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Dolly Anwar$b$, DATE '1948-07-01', DATE '1991-07-03', $b$Dolly Anwar (née Ibrahim; 1 July 1948 – 3 July 1991) was a Bangladeshi stage, television and film actress and writer and editor of Saatdin magazine. She was awarded Bangladesh National Film Award for Best Actress for her role in the film Surjo Dighol Bari (1979).

Source: Wikipedia — https://en.wikipedia.org/wiki/Dolly_Anwar$b$, 'en', NULL, $b$Film actor, Actor$b$, $b$Jashore District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$A. K. M. Fazlul Quader Chowdhury$b$, DATE '1919-03-26', DATE '1973-07-17', $b$A.K.M. Fazlul Quader Chowdhury (Bengali: এ.কে.এম. ফজলুল কাদের চৌধুরী; 1919–1973) was a Bengali politician who served as the 5th speaker of the National Assembly of Pakistan from East Pakistan. He belonged to Ayub Khan's Convention Muslim League. He was also the acting president of Pakistan from time to time when Ayub Khan left the country. His elder brother, Fazlul Kabir Chowdhury, was the leader of the opposition in the East Pakistan assembly. Quader was preceded by Maulvi Tamizuddin Khan of the Awami League.

Source: Wikipedia — https://en.wikipedia.org/wiki/A._K._M._Fazlul_Quader_Chowdhury$b$, 'en', NULL, $b$Politician$b$, $b$Raozan Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rosy Afsari$b$, DATE '1946-04-23', DATE '2007-03-09', $b$Rosy Afsary (Bengali: রোজী আফসারী, Bengali pronunciation: [rodʒi afsaɾi]; 23 April 1946 – 9 March 2007), also known as Rosy Samad, was an actress in the Bangladeshi film industry. She was awarded the Bangladesh National Film Award for Best Supporting Actress in its first ceremony in 1975 for her role in the film Lathial.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rosy_Afsari$b$, 'en', NULL, $b$Film actor, Actor$b$, $b$Lakshmipur$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Zohra Begum Kazi$b$, DATE '1912-10-15', DATE '2007-11-07', $b$Zohra Begum Kazi (15 October 1912 – 7 November 2007) was the first Bengali Muslim female physician. She was awarded the Tamgha-e-Pakistan in 1964, Begum Rokeya Padak in 2002, and the Ekushey Padak in 2008.

Source: Wikipedia — https://en.wikipedia.org/wiki/Zohra_Begum_Kazi$b$, 'en', NULL, $b$Physician$b$, $b$Durg$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khalil Ullah Khan$b$, DATE '1934-02-02', DATE '2014-12-07', $b$Khalil Ullah Khan (known as Khalil; 2 February 1934 – 7 December 2014) was a Bangladeshi film and television actor. He earned Bangladesh National Film Award for Best Supporting Actor for his role in Gunda in 1976.

Source: Wikipedia — https://en.wikipedia.org/wiki/Khalil_Ullah_Khan$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Khalil%20Ullah%20Khan%20in%202014.jpg?width=640$b$, $b$Actor$b$, $b$Sylhet District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Parveen Sultana Diti$b$, DATE '1965-03-31', DATE '2016-03-20', $b$Parveen Sultana (Bengali: পারভীন সুলতানা দিতি known by her stage name Diti; 31 March 1965 – 20 March 2016) was a Bangladeshi film and television actress. She won the Bangladesh National Film Award for Best Supporting Actress in 1987 for her performance in Swami Stree. She acted in more than 200 films in her career.

Starting her career with the film Daak Diye Jai, Diti quickly established herself as one of top actresses from mid 1980's to mid 1990's with movies such as Shami Stri, Benam Badshah, Strir Paona, Soshur Bari, Shesh Upohar, Mohan Bondhu, Mastan Raja, Bishash Obishash, Chakor, Doshi, Bishash Obishash, Chakor, Dui Jibon, Apon Ghor, Bheja Chokh, Lokkhir Songshar, Okritogo, Shomor, and Hingshar Agun.

Starting from the 1990's, she moved onto playing agrresive women centric action characters moving away from her original soft characters with movies such as Ajker Hungama, Khuner Bodla, Papi Shotru, Lady Inspector, Hotta, Bhai Keno Asami, Ojana Shotru, Shartophor, Bishash Obishash, Bhai Keno Asami, Hingshar Agun, Bachar Lorai, Khuner Bodla, Mukti Chai, Hotta, Polatok Ashami, Haramkhor, Beimani, Attoprokash. Her other notable movies during 1990's include Sukher Ghore Dukher Agun, Atto Bishash, Priyo Shotru, Manush, Sesh Protikkha, Luttoraj, Otikrom, Chakranter Shikar, Ashami Greftar, Amar Desh Amar Prem, Durjoy, Amma, Ami Ek Omanush, Chorom Aghat, Ochol Poysa, Raja Gunda, Kaliya, Bodla Nebo, and Shoth Manush.

Source: Wikipedia — https://en.wikipedia.org/wiki/Parveen_Sultana_Diti$b$, 'en', NULL, $b$Actor$b$, $b$Narayanganj$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Tazin Ahmed$b$, DATE '1975-07-30', DATE '2018-05-22', $b$Tazin Ahmed (30 July 1975 – 22 May 2018) was a Bangladeshi journalist, actress, playwright, director, and theater person. She won the 2003 Bachasas Award for the Best Actress in the drama category.

Source: Wikipedia — https://en.wikipedia.org/wiki/Tazin_Ahmed$b$, 'en', NULL, $b$Director, Journalist, Playwright, Actor$b$, $b$Noakhali District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$M. A. Wazed Miah$b$, DATE '1942-02-16', DATE '2009-05-09', $b$Mohammed Abdul Wazed Miah (6 February 1942 – 9 May 2009), locally known as, Sudha Mia, was a Bangladeshi physicist and the writer of a number of texts in physics and some political history books, a former chairman of the Bangladesh Atomic Energy Commission and husband of former prime minister of Bangladesh Sheikh Hasina.

Source: Wikipedia — https://en.wikipedia.org/wiki/M._A._Wazed_Miah$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/M.%20A.%20Wazed%20Miah%20in%201997.png?width=640$b$, $b$Nuclear physicist, Physicist, Writer$b$, $b$Pirganj Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Matia Chowdhury$b$, DATE '1942-06-30', DATE '2024-10-16', $b$Matia Chowdhury (Bengali: মতিয়া চৌধুরী, romanized: Matiẏā caudhurī; 30 June 1942 – 16 October 2024) was an Awami League leader. She was a deputy leader of parliament, and a Jatiya Sangsad member representing the Sherpur-2 constituency from 2009 to 2024. She held the position of minister of agriculture under the first, second and third premierships of Sheikh Hasina, from 1996 to 2001 and then again from 2009 to 2019 during the periods when the Bangladesh Awami League held power.

She was accused as a perpetrators of the July massacre orchestrated and executed by Sheikh Hasina's toppled regime.

Source: Wikipedia — https://en.wikipedia.org/wiki/Matia_Chowdhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Matia%20Chowdhury%20at%20IRRI.jpg?width=640$b$, $b$Politician$b$, $b$Pirojpur District$b$, $b$Evercare Hospital Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nurjahan Murshid$b$, DATE '1925-05-22', DATE '2003-09-01', $b$Nurjahan Murshid (née Beg; 22 May 1924 – 1 September 2003) was a journalist and teacher, a Bangladesh cabinet minister, and social activist.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nurjahan_Murshid$b$, 'en', NULL, $b$Academic, Politician$b$, $b$Taranagar$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Maqbul Ahmad$b$, DATE '1939-08-02', DATE '2021-04-13', $b$Maqbul Ahmad (2 August 1939 – 13 April 2021) was a Bangladeshi politician and cleric who served as the 3rd emir of the Bangladesh Jamaat-e-Islami from 2016 to 2019. He was appointed as emir in October 2016 after serving as acting emir for six months.

Source: Wikipedia — https://en.wikipedia.org/wiki/Maqbul_Ahmad$b$, 'en', NULL, $b$Politician$b$, $b$Daganbhuiyan Upazila$b$, $b$Ibn Sina Medical College$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khondakar Ashraf Hossain$b$, DATE '1950-01-04', DATE '2013-06-16', $b$Khondakar Ashraf Hossain (Bengali: খোন্দকার আশরাফ হোসেন; 4 January 1950 – 16 June 2013) was a leading postmodernist poet, essayist, translator, and editor from Bangladesh. He wrote more than eighteen titles.

Source: Wikipedia — https://en.wikipedia.org/wiki/Khondakar_Ashraf_Hossain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dr.%20Hossain.jpg?width=640$b$, $b$Literary scholar, Linguist, Academic, Poet$b$, $b$Jamalpur Sadar Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Hamoodur Rahman$b$, DATE '1910-11-01', DATE '1975-10-13', $b$Chief Justice Hamoodur Rahman (Urdu: حمود الرحمن; 1 November 1910 – 20 December 1981), NI. HI, was a Pakistani Bengali jurist and an academic who served as the Chief Justice of Pakistan from 18 November 1968 until 31 October 1975.

Educated in law and trained as a jurist in the United Kingdom, he chaired the War Enquiry Commission to investigate the causes of the Bangladesh Liberation War that led to the creation of Bangladesh. In addition, Rahman served as a law professor in the faculty of Karachi University and vice-chancellor of the University of Dhaka while remaining active in promoting literacy across the country. After the independence of Bangladesh, Rahman's family retained Pakistan's citizenship, and his son served as the Chief Justice of Islamabad High Court.

Chief Justice Rahman remained a respected figure in Pakistan's judiciary, and is hailed for his honesty and patriotism. Senior Justice Khalil-ur-Rehman Ramday once publicly noted that "his Commission was the most honourable commission that was investigated by a Bengali Chief Justice, in spite of East-Pakistan disaster." His findings, which exposed the Bangladesh genocide and recommended charges for senior Pakistani officials, were never made public, as the report was muzzled by the Bhutto administration under the guise of harming civil-military relations.

Source: Wikipedia — https://en.wikipedia.org/wiki/Hamoodur_Rahman$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Hamoodur%20Rahman.jpg?width=640$b$, $b$Philosopher, Judge$b$, $b$Chittagong$b$, $b$Karachi$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shahid Qadri$b$, DATE '1942-08-14', DATE '2016-08-28', $b$Shahid Quadri (Bengali pronunciation: [ʃoɦid̪ kad̪ɾi]; also spelt Shaheed Quaderi; 14 August 1942 – 28 August 2016) was a Bangladeshi poet and writer. For his poetry, he was awarded Bangla Academy Literary Award in 1973 and Ekushey Padak in 2011. His notable poems include "Uttoradhikar", "Tomake Obhibadon Priyotoma", "Kothao Kono Krondon Nei" and "Amar Chumbongulo Poucchey Dao".

Source: Wikipedia — https://en.wikipedia.org/wiki/Shahid_Qadri$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Dhaka$b$, $b$New York City$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Dwijen Sharma$b$, DATE '1929-05-29', DATE '2017-09-15', $b$Dwijen Sharma (29 May 1929 – 15 September 2017) was a Bangladeshi naturalist and science writer. He was awarded Bangla Academy Literary Award in 1987 and Ekushey Padak in 2015 by the Government of Bangladesh for his contribution in language and literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Dwijen_Sharma$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dwijen%20Sharma.jpg?width=640$b$, $b$Translator, Teacher, Writer, Naturalist$b$, $b$Barlekha Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Utpala Sen$b$, DATE '1924-03-12', DATE '2005-05-13', $b$Utpala Sen (12 March 1924 – 13 May 2005) was a prominent Indian Bengali playback singer. She was a very popular playback singer of her time in the 1950s alongside Sandhya Mukherjee, Pratima Banderjee, Alpana Banerjee, etc. She has sung numerous duets with prominent male singers such as Hemanta Mukherjee, Manna Dey and also her husband, Satinath Mukherjee.

Source: Wikipedia — https://en.wikipedia.org/wiki/Utpala_Sen$b$, 'en', NULL, $b$Singer$b$, $b$Dhaka$b$, $b$Kolkata$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Braja Bihari Barua$b$, DATE '1936-03-03', DATE '2014-04-12', $b$Braja Bihari Barua (3 March 1935 – 12 April 2014) was a Bangladeshi war veteran, politician, and social worker. He took part in the Bangladesh Liberation War in 1971 under Sector 1 as a member of the Mukti Bahini.

He later became known for his social work in the Bandarban region and was locally recognized for his community service and spiritual activities.

Source: Wikipedia — https://en.wikipedia.org/wiki/Braja_Bihari_Barua$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Braja%20Bihari%20Barua.jpg?width=640$b$, $b$Freedom fighter, Socialite, Politician, Writer$b$, NULL, $b$Chittagong Medical College$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Jahanara Arzu$b$, DATE '1932-11-17', DATE '2026-03-02', $b$Jahanara Arzu (17 November 1932 – 2 March 2026) was a Bangladeshi poet. She was awarded Ekushey Padak in 1987 by the Government of Bangladesh for her contribution to Bengali literature. Arzu and Sufia Kamal were the founding editors of Sultana, the first women's weekly published from East Bengal on 14 January 1949.

Arzu was married to a former Vice President of Bangladesh and Justice A. K. M. Nurul Islam. Together, they had two sons including Justice Md. Ashfaqul Islam and professor Minara Zahan. Arzu died on 2 March 2026, at the age of 93.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jahanara_Arzu$b$, 'en', NULL, $b$Journalist, Poet, Writer$b$, $b$Manikganj District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Robin Ghosh$b$, DATE '1939-09-13', DATE '2016-02-13', $b$Robin Ghosh (Bengali: রবিন ঘোষ, Urdu: روبن گھوش; 13 September 1939 – 13 February 2016) was a Pakistani-Bangladeshi playback singer and film music composer, best known for singing and composing music for Lollywood films from 1961 to 1986. Robin Ghosh had a notable contribution in establishing career of Playback singer Ahmed Rushdi and to his success. Ghosh gained fame in the mid-1960s when Rushdi sang his compositions in films like Chakori (1967), Jahan Tum Wahan Hum, Paisa, etc.

Source: Wikipedia — https://en.wikipedia.org/wiki/Robin_Ghosh$b$, 'en', NULL, $b$Composer$b$, $b$Baghdad$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Moni Singh$b$, DATE '1900-07-19', DATE '1990-12-31', $b$Moni Singh (Bengali: মনি সিং; 28 June 1901 – 31 December 1990), also known by the pseudonym Comrade Moni Singh, was a Bangladeshi politician and the founder of the Communist Party of East Pakistan.

Singh operated a guerrilla wing of the Mukti Bahini during the Bangladesh Liberation War in 1971 and was an adviser to the Provisional Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Moni_Singh$b$, 'en', NULL, $b$Trade unionist, Politician, Writer$b$, $b$Durgapur$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Belal Muhammad$b$, DATE '1936-02-20', DATE '2013-07-30', $b$Belal Mohammad (20 February 1936 – 30 July 2013) was one of the founders of the Swadhin Bangla Betar Kendra.

Source: Wikipedia — https://en.wikipedia.org/wiki/Belal_Muhammad_(activist)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Belal%20Muhammad%20delivering%20speech.jpg?width=640$b$, $b$Writer$b$, $b$Sandwip$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Alauddin Al-Azad$b$, DATE '1932-05-06', DATE '2009-07-03', $b$Alauddin Al-Azad (6 May 1932 – 3 July 2009) was a modern Bangladeshi author, novelist, and poet.

Source: Wikipedia — https://en.wikipedia.org/wiki/Alauddin_Al-Azad$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Alauddin%20Al%20Azad.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Prabir Mitra$b$, DATE '1941-08-18', DATE '2025-01-05', $b$Probir Mitra (Bengali: প্রবীর মিত্র; 18 August 1941 – 5 January 2025), later adopted Hasan Imam (Bengali: হাসান ইমাম), was a Bangladeshi film actor. He won Bangladesh National Film Award for Best Supporting Actor for his performance in the film Boro Bhalo Lok Chhilo in 1982. He also won the 2018 Lifetime Achievement Award. As of 2019, he had worked on over 400 films.

Source: Wikipedia — https://en.wikipedia.org/wiki/Prabir_Mitra$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Prabir%20Mitra%20%281%29%20%28cropped%29.jpg?width=640$b$, $b$Film actor, Television actor$b$, $b$Chandina$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sheikh Fazlul Haque Mani$b$, DATE '1939-04-12', DATE '1975-08-15', $b$Sheikh Fazlul Haque Moni (4 December 1939 – 15 August 1975) was a Bangladeshi politician. He was one of the nephews of Sheikh Mujibur Rahman, the founding father of Bangladesh. He was one of the founders of Mujib Bahini Bangladesh Liberation Force - BLF one of the major guerrilla forces of the Bangladesh Liberation War, and also the founder of Bangladesh Awami Jubo League, the youth wing of Bangladesh Awami League.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sheikh_Fazlul_Haque_Mani$b$, 'en', NULL, $b$Revolutionary, Journalist, Politician, Writer$b$, $b$Tungipara Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Subhash Dutta$b$, DATE '1930-02-09', DATE '2012-11-16', $b$Subhash Dutta (9 February 1930 – 16 November 2012) was a Bangladeshi filmmaker, theater and film actor. He started his career as a commercial artist. Dutta was heavily influenced by Satyajit Ray and his deep affection towards Satyajit earned him the nickname "Duttajit".

Source: Wikipedia — https://en.wikipedia.org/wiki/Subhash_Dutta$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Suvash%20Datta%202012.jpg?width=640$b$, $b$Film producer, Film director, Actor, Screenwriter$b$, $b$Dinajpur District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khaleda Ekram$b$, DATE '1950-08-06', DATE '2016-05-24', $b$Khaleda Ekram (6 August 1950 – 24 May 2016) was a Bangladeshi architect, professor, researcher, and academic. She served as the 12th vice-chancellor of Bangladesh University of Engineering and Technology (BUET). She was the former dean of the faculty of architecture and planning and head of the department of architecture at BUET. She was the first woman to be appointed as the vice-chancellor of BUET. She held the position from September 2014 until her death in May 2016.

Ekram was awarded 2023 Begum Rokeya Padak posthumously for her contribution to women's education

Source: Wikipedia — https://en.wikipedia.org/wiki/Khaleda_Ekram$b$, 'en', NULL, $b$Vice-chancellor, Architect$b$, $b$Dhaka$b$, $b$Bangkok$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shah Abdul Karim$b$, DATE '1916-02-15', DATE '2009-09-12', $b$Baul Shah Abdul Karim (Bengali: শাহ আবদুল করিম; 15 February 1916 – 12 September 2009) was a Bangladeshi Baul musician and philosopher. Widely regarded as one of the greatest Baul musicians of all time, he was called Baul Samrat (The Baul Emperor). The Government of Bangladesh awarded him the Ekushey Padak, the country's second highest civilian decoration, in 2001. Alongside his enormous discography of Baul music, Karim had contributed significantly to developing the Baul philosophy; his work is generally seen as the refined continuation of classic Bauls like Fakir Lalon Shah. Beyond Baulism, Karim's multidisciplinary contribution to several sectors, including body theory, Sufism, Ma'rifa, and revolutionary music has made him one of the enduring examples of Bangladeshi secular pluralism.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shah_Abdul_Karim$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Shah%20Abdul%20Karim.jpg?width=640$b$, $b$Music director, Lyricist, Songwriter, Singer$b$, $b$Derai Upazila$b$, $b$Sylhet$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Mainul Hossain$b$, DATE '1951-03-17', DATE '2014-11-10', $b$Syed Mainul Hossain (17 March 1952 – 10 November 2014) was a Bangladeshi structural engineer and architect. He is the designer of the National Martyrs' Memorial, one of the national landmarks of Bangladesh. He was posthumously awarded the Independence Award in 2022.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Mainul_Hossain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mainul%20Hossen%20%282%29.JPG?width=640$b$, $b$Engineer, Architect$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ahmed Rafiq$b$, DATE '1929-09-12', DATE '2025-10-02', $b$Ahmed Rafiq (12 September 1929 – 2 October 2025) was a Bangladeshi language movement activist, writer and researcher on Rabindranath Tagore and his literature. He achieved Ekushey Padak in 1995 by the Government of Bangladesh. Tagore Research Institute in Kolkata conferred the Rabindratattacharya title on him in 2011.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ahmed_Rafiq$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Ahmed%20Rafik%202009.jpg?width=640$b$, $b$Physician, Writer$b$, $b$Shahbazpur, Brahmanbaria$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rabeya Khatun$b$, DATE '1935-12-27', DATE '2021-01-03', $b$Rabeya Khatun (27 December 1935 – 3 January 2021) was a Bangladeshi novelist. She wrote over 50 novels and more than 400 short stories. Her works also include essays, research, religious history, and travelogues. She was awarded Bangla Academy Literary Award in 1973, Ekushey Padak in 1993, and Independence Day Award in 2017 by the Government of Bangladesh.

Khatun died of cardiac arrest on 3 January 2021 at her residence in Gulshan, Dhaka.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rabeya_Khatun$b$, 'en', NULL, $b$Writer$b$, $b$Bikrampur$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mokbula Manzoor$b$, DATE '1938-09-14', DATE '2020-07-03', $b$Makbula Manzoor or Mokbula Manzoor (Bengali: মকবুলা মনজুর; 14 September 1938 – 3 July 2020) was a Bangladeshi author and novelist. Her literary works are considered to have played a significant role in the creation of modern Bangladeshi literature. Author Syedur Rahman cites her together with Akhtaruzzaman Ilias, Selina Hossain and Hasan Hafizur Rahman as one of the notable contributors to modern Bangladeshi literature.

Makbula Manzoor is noted for writing from a woman's perspective in a male-dominated society; her 1998 novel Kaler Mandira is one such example, and references female exploitation during the Bangladesh Liberation War in 1971. She is considered to be an outstanding Bangladeshi female writer, inspired by the events which led to the creation of the country in 1971. Makbula is renowned for her novels, short stories and articles. A superb story-teller, Makbula has skillfully portrayed the socio-political history of Bangladesh and the endless struggle of ordinary men and women. She dedicated her writing to both children and adolescents, as well as adult fiction. Makbula received many national awards in recognition of her contribution to Bengali literature.

As a professor of Bengali literature, Makbula taught generations of students.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mokbula_Manzoor$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Makbula%20Manzoor%20.jpg?width=640$b$, $b$Novelist, Teacher, Writer$b$, $b$Bardhaman district$b$, $b$Uttara$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Muhammad Mansuruddin$b$, DATE '1904-01-31', DATE '1987-09-19', $b$Muhammad Mansuruddin (31 January 1904 – 19 September 1987) was a Bengali author, literary critic, essayist, lexicographer and biographer from Bangladesh. He was an authority on folklore and was famous for a huge collection of age-old folk songs, mostly anthologised in thirteen volumes under the title Haramoni. In recognition of his lifelong contribution to folklore collection and research, the Rabindra Bharati University awarded him D.Litt. degree in 1987.

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Mansuruddin$b$, 'en', NULL, $b$Writer$b$, $b$Pabna$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Naiyyum Choudhury$b$, DATE '1946-09-27', DATE '2019-09-07', $b$Naiyyum Choudhury (27 September 1944 – 7 September 2019) was a Bangladeshi biotechnologist and a nuclear scientist. He pioneered the development and adoption of the National Biotechnology policy of Bangladesh. He served as the Chairman of Bangladesh Atomic Energy Commission, and also served in many important positions in Bangladesh. He was serving as the founding Chairman of Bangladesh Atomic Energy Regulatory Authority (BAERA) at the time of his death. He was the Chairman of the Department of Microbiology, Dhaka University, Professor and Coordinator of Biotechnology at BRAC University, and served as faculty member in Jahangir Nagar University and BUET. He was also the IAEA Regional Cooperation Agreement (RCA) Chair person. He was also a fellow of Bangladesh Academy of Sciences (BAS), and was serving as the Vice President of BAS at the time of his death. He was also the contact person for Inter Academic Panel (IAP) of Bangladesh.

Choudhury also organised a number of international seminars and symposiums.

Source: Wikipedia — https://en.wikipedia.org/wiki/Naiyyum_Choudhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Naiyyum%20Choudhury.JPG?width=640$b$, $b$Biochemist, Academic$b$, $b$Cumilla$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shushama Das$b$, DATE '1930-05-01', DATE '2025-03-26', $b$Shushama Das (Bengali: সুষমা দাস; 1 May 1930 – 26 March 2025) was a Bangladeshi folk singer, who was awarded Ekushey Padak by the Government of Bangladesh in 2017.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shushama_Das$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sushoma%20Das%20Dhaka%202017.jpg?width=640$b$, $b$Singer$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sultana Kamal$b$, DATE '1952-12-10', DATE '1975-08-15', $b$Sultana Kamal (née Sultana Ahmed; 10 December 1952 – 15 August 1975), nicknamed Khuki, was a Bangladeshi female athlete. She became the first woman Blue of Dhaka University in 1970. Sultana was married to Sheikh Kamal, the eldest son of Bangladesh's founding President Sheikh Mujibur Rahman. She was killed on 15 August 1975, during the assassination of Sheikh Mujibur Rahman family.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sultana_Kamal_(athlete)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sultana%20Kamal%20Khuki.jpg?width=640$b$, $b$Athletics competitor$b$, NULL, $b$Dhanmondi Thana$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sadek Bachchu$b$, DATE '1955-01-01', DATE '2020-09-14', $b$Mahbub Ahmed Sadek (Bengali: মাহবুব আহমেদ সাদেক; known as Sadek Bachchu (Bengali: সাদেক বাচ্চু); 1 January 1955 – 14 September 2020) was a Bangladeshi film actor. He also appeared in television dramas and theatre. He won Bangladesh National Film Award for Best Actor in Negative Role for the film Ekti Cinemar Golpo (2018).

Source: Wikipedia — https://en.wikipedia.org/wiki/Sadek_Bachchu$b$, 'en', NULL, $b$Actor$b$, $b$Haziganj Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mirza Mazharul Islam$b$, DATE '1927-01-01', DATE '2020-10-11', $b$Mirza Mazharul Islam (1 January 1927 – 11 October 2020) was a Bangladeshi surgeon and language movement veteran.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mirza_Mazharul_Islam$b$, 'en', NULL, $b$Physician$b$, $b$Tangail District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sufia Ahmed$b$, DATE '1932-11-20', DATE '2020-04-09', $b$Sufia Ahmed (née Ibrahim; 20 November 1932 – 9 April 2020) was a Bangladeshi academic. She was selected as the first female National Professor of Bangladesh in January 1995. She was awarded Ekushey Padak in 2002 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sufia_Ahmed$b$, 'en', NULL, $b$Professor$b$, $b$Faridpur District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nadira Begum$b$, NULL, DATE '2023-11-06', $b$Nadira Begum (died 6 November 2023) was a Bangladeshi folk singer. She was awarded Shilpakala Padak by the Government of Bangladesh in 2015. She was notable for songs like Kolo Kolo Cholo Cholo Nodi Kore Tolmolo.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nadira_Begum$b$, 'en', NULL, $b$Singer$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Jamilur Reza Choudhury$b$, DATE '1943-11-15', DATE '2020-04-28', $b$Dr. Jamilur Reza Choudhury (15 November 1942 – 28 April 2020) was a Bangladeshi civil engineer, professor, researcher, and education advocate. He was an Adviser (Minister) to Caretaker Government of Bangladesh (April–June 1996). He was the first vice chancellor of BRAC University and former vice chancellor of University of Asia Pacific. He was also the president of Bangladesh Mathematical Olympiad Committee from 2003. He was awarded Ekushey Padak by the Government of Bangladesh in the category of science and technology in 2017. He was inducted as a National Professor by the Government of Bangladesh in 2018.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jamilur_Reza_Choudhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Jamilur%20Reza%20Choudhury%20%2818%29%20%28cropped%29.jpg?width=640$b$, $b$Civil engineer, Engineer$b$, $b$Sylhet$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Jayashree Kabir$b$, NULL, DATE '2026-01-12', $b$Jayashree Kabir (née Roy; 22 June 1952 – 12 January 2026) was a Bangladeshi Bengali film actress. She acted in around 30 films in West Bengal and Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jayashree_Kabir$b$, 'en', NULL, $b$Actor$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kamal Uddin Siddiqui$b$, DATE '1945-10-22', DATE '2025-11-03', $b$Kamal Uddin Siddiqui (22 October 1945 – 3 November 2025) was a Bangladeshi economist and social scientist. He was a faculty member of Monash University.

In 1971, he participated in the Liberation War of Bangladesh. A career civil servant, he served as the principal secretary to Prime Minister Khaleda Zia until 2006. He was nominated by Bangladesh for election to the United Nations Committee on the Rights of the Child, and served from 2005 to 2009. He was, until 2006, chief editor of the Encyclopedia of Flora and Fauna of Bangladesh, the first volumes of which were published in 2008 by the Asiatic Society of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Kamal_Uddin_Siddiqui$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Kamal%20Siddiqui%20in%202006.JPG?width=640$b$, $b$Sociologist, Author, Economist$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Abdus Samad$b$, NULL, DATE '2021-07-28', $b$Syed Abdus Samad (1942 – 28 July 2021) was a teacher of economics. He was a faculty member at the University of Dhaka, Boston State College, Boston University, the University of the South Pacific, and the Hankuk University of Foreign Studies, South Korea. Samad worked as a national and international civil servant, economist, and human rights activist. In Bangladesh, he was the permanent secretary to the Ministry of Energy and Mineral Resources, and a principal secretary to the Prime Minister. Samad was the executive chairman of the Bangladesh Board of Investment.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Abdus_Samad$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dr.%20Syed%20Abdus%20Samad.jpg?width=640$b$, $b$Human rights defender, Civil servant, Economist$b$, $b$Bangladesh$b$, $b$Baridhara$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ekhlasuddin Ahmed$b$, DATE '1940-12-16', DATE '2014-12-24', $b$Ekhlasuddin Ahmed (15 December 1940 – 24 December 2014) was a Bangladeshi children's writer. He was awarded the Ekushey Padak, one of the highest civilian awards in Bangladesh, in 2000.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ekhlasuddin_Ahmed$b$, 'en', NULL, $b$Children's writer, Writer$b$, $b$24 Parganas district$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Farrukh Ahmad$b$, DATE '1918-07-10', DATE '1974-10-19', $b$Syed Farrukh Ahmad (Bengali: সৈয়দ ফররুখ আহমদ; 10 June 1918 – 19 October 1974), later simply known as Farrukh Ahmad, was a Bangladeshi poet and author. He is commonly known as the poet of the Muslim renaissance, as many of his poems embody the spirit of resurrection in the hearts of the colonised Muslims of Bengal. Other than being a distinguished bearer of Islamic thought in modern Bengal, his poetry is also significant for its diction and literary value. The transition from romanticism to modernism is evident in his poetry and he is best known for his magnum opus, Sat Sagorer Majhi.

Source: Wikipedia — https://en.wikipedia.org/wiki/Farrukh_Ahmad$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Magura District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Hayat Saif$b$, DATE '1942-12-16', DATE '2019-05-13', $b$Saiful Islam Khan (known as Hayat Saif; 16 December 1942 – 13 May 2019) was a twentieth century modern Bengali poet and literary critic from Bangladesh. A career bureaucrat, he retired in 2000 and since then was engaged in the corporate private sector and divided his time in World Scouting and literary and artistic pursuits. He has been translated in English and Spanish and, in Bangladesh, is generally acclaimed as an intellectual interpreter of contemporary life and culture.

Saif assumed this pen name in 1961 when contributing to literary journals. In 2005, he was awarded the 305th Bronze Wolf. He was awarded Ekushey Padak in 2018 for his contribution in language and literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Hayat_Saif$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Hayat%20Saif%202009.JPG?width=640$b$, $b$Poet, Writer$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abdur Razzak$b$, DATE '1942-01-23', DATE '2017-08-21', $b$Mohammad Abdur Razzak (Bengali: [abd̪uɾ razːak] ; 23 January 1942 – 21 August 2017), known professionally as Razzak, was a Bangladeshi actor, producer, and director who was predominantly worked in Dhallywood cinema. Widely regarded as one of the greatest and most successful actors in the history of Bangladeshi cinema, he was referred to in the media as "Nayak Raj", a term introduced by Ahmed Zaman Chowdhury, editor of the film magazine Chitrali.

His debut film as a producer was with the film Akankha (1976), directed by Subhash Dutta, and it was produced under his own production company, Rajlokkhi Productions. Razzak won the Bangladesh National Film Award for Best Actor five times for his roles in the films Ki Je Kori (1976), Ashikkhito (1978), Boro Bhalo Lok Chhilo (1982), Chandranath (1984), and Jogajog (1988). He was awarded the Independence Award in 2015 by the government of Bangladesh. He acted in more than 300 Bangladeshi and Indian Bengali and Urdu films, and also directed 16 films.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdur_Razzak_(actor)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Abdur%20Razzak%2C%20Ganabhaban%20Dhaka%202016-06-28%20%28cropped%29.jpg?width=640$b$, $b$Film producer, Film director, Actor$b$, $b$Kolkata$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abul Fazal$b$, DATE '1903-07-01', DATE '1983-05-04', $b$Abul Fazal (1 July 1903–4 May 1983) was a Bangladeshi writer and academic. He served as the 4th vice-chancellor of the University of Chittagong. He was awarded the Bangla Academy Literary Award in 1962 and Independence Day Award in 2012 (posthumously).

Source: Wikipedia — https://en.wikipedia.org/wiki/Abul_Fazal_(writer)$b$, 'en', NULL, $b$Writer$b$, $b$Satkania Upazila$b$, $b$Chattogram Division$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abul Kalam Shamsuddin$b$, DATE '1897-11-03', DATE '1978-03-04', $b$Abul Kalam Shamsuddin (3 November 1897 – 4 March 1978) was a journalist, writer and politician.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abul_Kalam_Shamsuddin$b$, 'en', NULL, $b$Journalist, Politician, Writer$b$, $b$Trishal Upazila$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Samar Das$b$, DATE '1929-12-10', DATE '2001-09-25', $b$Samar Das (Bengali: সমর দাস; 10 December 1929 – 25 September 2001) was a Bangladeshi musician and composer. He became one of the most important music directors in Pakistan and subsequently Bangladesh and was the composer of over 2,000 songs.

Source: Wikipedia — https://en.wikipedia.org/wiki/Samar_Das$b$, 'en', NULL, $b$Singer, Composer$b$, $b$Dhaka$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Safiuddin Ahmed$b$, DATE '1922-06-23', DATE '2012-05-20', $b$Safiuddin Ahmed (23 June 1922 – 20 May 2012) was a Bangladeshi artist. He was awarded Ekushey Padak in 1978 and Independence Day Award in 1996 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Safiuddin_Ahmed$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Young%20Safiuddin%20Ahmed.jpg?width=640$b$, $b$Printmaker, Graphic artist, Painter$b$, $b$Kolkata$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Selim Al Deen$b$, DATE '1949-08-18', DATE '2008-01-14', $b$Muhamed Mianudin Ahmed (18 August 1949 – 14 January 2008) was a Bangladeshi playwright and theatre artist. He was the founder chairperson of the Department of Drama and Dramatics at Jahangirnagar University. He was awarded Bangla Academy Literary Award in 1984 and Ekushey Padak in 2007 by the Government of Bangladesh for his contribution to theatre and won the Independence Award in 2023 for his contribution to the field of literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Selim_Al_Deen$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A6%B8%E0%A7%87%E0%A6%B2%E0%A6%BF%E0%A6%AE%20%E0%A6%86%E0%A6%B2%20%E0%A6%A6%E0%A7%80%E0%A6%A8.jpg?width=640$b$, $b$Writer$b$, $b$Sonagazi Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Brojen Das$b$, DATE '1927-12-09', DATE '1998-06-01', $b$Brojen Das (Bengali: ব্রজেন দাস; 9 December 1927 – 1 June 1998) was a Bangladeshi (East Pakistan) swimmer who was the first Asian to swim across the English Channel and the first person to cross it six times.

Source: Wikipedia — https://en.wikipedia.org/wiki/Brojen_Das$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Brojen%20das.jpg?width=640$b$, $b$Swimmer$b$, $b$Bikrampur$b$, $b$Kolkata$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Serajul Alam Khan$b$, DATE '1941-01-06', DATE '2023-06-09', $b$Nizam Mohammad Serajul Alam Khan (6 January 1941 – 9 June 2023), commonly known as Serajul Alam Khan (Bengali: সিরাজুল আলম খান), also called as Dada, Dadabhai and by his initials SAK, was a Bangladeshi politician, political analyst, philosopher and writer who spearheaded the Bangladesh liberation movement but also became one of the controlling forces of political polarization in post-independence Bangladesh.

Serajul Alam Khan joined politics in the 1950s–60s as a student and quickly rose to the helm of Chhatra League, the student wing affiliated with the Bengali nationalist Awami League party in Pakistan. He, along with others, founded the Swadhin Bangla Biplobi Parishad (which came to be known as 'Nucleus'), a secret organization whose existence is not directly documented but strongly supported by popular hearsay and conventional history. The organization played a significant role in the Bangladesh Liberation War. He along with Tofael Ahmed, Sheikh Fazlul Haque Moni and Abdur Razzaq formed and commanded the Mujib Bahini (a.k.a. Bangladesh Liberation Force).

Source: Wikipedia — https://en.wikipedia.org/wiki/Serajul_Alam_Khan$b$, 'en', NULL, $b$Political theorist, Politician$b$, $b$Begumganj Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ashab Uddin Ahmad$b$, NULL, DATE '1994-05-28', $b$Ashab Uddin Ahmad (Bengali: আসহাব উদ্দীন আহমদ; April 1914 – 28 May 1994) was a Bangladeshi writer, educator and politician. He was a member of the East Bengal Legislative Assembly for the United Front, and a Communist activist. In 2005, he was posthumously awarded the Ekushey Padak, one of the highest civilian awards in Bangladesh, for his contributions to literature, which include 24 published books in Bengali and English.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ashab_Uddin_Ahmad$b$, 'en', NULL, $b$Politician, Writer$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Mohammad Ali$b$, DATE '1928-12-05', DATE '1993-10-17', $b$Syed Mohammad Ali (9 December 1928 – 17 October 1993) was a Bengali journalist and editor. Ali began his career in East Pakistan. He became an editor for several newspapers in East Asia, including The Bangkok Post in Thailand, the Hong Kong Standard in British Hong Kong and The New Nation in Singapore. Ali also worked for UNESCO. In 1991, Ali founded The Daily Star in Bangladesh during the country's democratic transition.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Mohammad_Ali$b$, 'en', NULL, $b$Journalist$b$, $b$Maulvi Bazar$b$, $b$Bangkok$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$M. Harunur Rashid$b$, DATE '1939-12-28', DATE '2024-11-26', $b$M. Harunur Rashid (28 December 1939 – 26 November 2024) was a Bangladeshi academic, educational administrator, editor, and translator. He was a noted writer of Sufism and Sufi literature and a commentator of social, political, and literary texts.

Source: Wikipedia — https://en.wikipedia.org/wiki/M._Harunur_Rashid$b$, 'en', NULL, $b$Writer$b$, $b$Assam$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Alauddin Ali$b$, DATE '1952-12-24', DATE '2020-08-09', $b$Alauddin Ali (24 December 1952 – 9 August 2020) was a Bangladeshi music composer. He won the Bangladesh National Film Award for Best Music Director eight times for the films Golapi Ekhon Traine (1978), Sundori (1979), Koshai (1980), Jogajog (1988) and Lakhe Ekta (1990). He won the Best Music Composer award for the film Laal Doriya (2002) and the Best Lyrics award for Premik (1985). Moreover, he won the Ifad Film Club Award and the Bachsas Award in the category of Best Music Director. He directed music for more than 300 films.

Source: Wikipedia — https://en.wikipedia.org/wiki/Alauddin_Ali$b$, 'en', NULL, $b$Composer$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Maqsudul Alam$b$, DATE '1954-12-14', DATE '2014-12-20', $b$Maqsudul Alam (Bengali: মাকসুদুল আলম; 14 December 1954 – 20 December 2014) was an East Bengal-born life-science scientist who is known for his work on genome sequencing. His work on genome sequencing started with bacteria Idiomarina loihiensis in 2003. He came into the focus of Bangladeshi people after his work on genome sequencing of jute species and jute attacking fungus.

Source: Wikipedia — https://en.wikipedia.org/wiki/Maqsudul_Alam$b$, 'en', NULL, $b$Geneticist$b$, $b$Faridpur Sadar Upazila$b$, $b$Honolulu$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mustafa Nur-Ul Islam$b$, NULL, DATE '2018-05-09', $b$Mustafa Nur-Ul Islam (1 May 1927 – 9 May 2018) was a Bangladeshi academic. In 2011, he was appointed a National Professor of Bangladesh. He was awarded Ekushey Padak in 1981 and Independence Day Award in 2010 by the Government of Bangladesh.

He was the founder director of Bangladesh Shilpakala Academy, the Director General of Bangla Academy and the Chairman of Bangladesh National Museum. In 2011, he was appointed a National Professor. He edited a literary magazine named Sundaram.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mustafa_Nur-Ul_Islam$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mustafa%20Nurul%20Islam%202009.jpg?width=640$b$, $b$Academic, Educator$b$, $b$Bogura District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mohammad Kibria$b$, DATE '1929-01-01', DATE '2011-06-07', $b$Mohammad Kibria (c. 1929 – 7 June 2011) was a Bangladeshi artist. He was awarded Ekushey Padak in 1983 and Independence Day Award in 1999 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mohammad_Kibria$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mohammad%20Kibria%201958.jpg?width=640$b$, $b$Painter$b$, $b$Birbhum district$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Binod Bihari Chowdhury$b$, DATE '1911-01-10', DATE '2013-04-10', $b$Binod Bihari Chowdhury (Bengali: বিনোদ বিহারী চৌধুরী; 10 January 1911 – 10 April 2013) was a Bangladeshi social worker and anti-colonial revolutionary. An influential member in the Indian independence movement and veteran of the civil society of Bangladesh, he is mostly known for his participation in the Chittagong armoury raid, an armed uprising led by Surya Sen to uproot the British colonial rule in India in 1930.

Born in 1911, in Chittagong, Binod Bihari was the last surviving veteran of the Chittagong armoury raid and was active in many significant events in the history of Bangladesh. In 2000, he received the Independence Day Award, the highest civilian award in Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Binod_Bihari_Chowdhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Binod%20behari%20choudhury.jpg?width=640$b$, $b$Revolutionary$b$, $b$Chattogram District$b$, $b$Kolkata$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abul Kashem Fazlul Haq$b$, DATE '1944-09-30', DATE '2026-07-05', $b$Abul Kashem Fazlul Haq (30 September 1940 – 5 July 2026) was a Bangladeshi writer, essayist, translator, critic, columnist and activist. He was a professor of Bengali language and literature at the University of Dhaka. He was the convener of Rashtrabhasha Bangla Rokkha Komiti (State Language Bengali Protection Committee). He received the Bangla Academy Literary Award in 1981. On 27 October 2024, the interim government appointed Haq as the new president of Bangla Academy for a three-year term.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abul_Kashem_Fazlul_Haq$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Abul%20Quasem%20Fazlul%20Huq.jpg?width=640$b$, $b$Essayist, Editor, University teacher, Writer$b$, $b$Kishoreganj District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ehtesham$b$, DATE '1927-10-12', DATE '2002-02-17', $b$Ehtesham ur Rahman (1927 – 17 February 2002), known as Captain Ehtesham, was a Bangladeshi and Pakistani film director. On his death in 2002 he was described as a pioneer of the film industry in Dhaka, and one of Bangladesh's leading directors.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ehtesham$b$, 'en', NULL, $b$Film director, Screenwriter$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Washiqur Rahman$b$, DATE '1988-06-01', DATE '2015-03-30', $b$Attacks by Islamist extremists in Bangladesh took place during a period of turbulence in Bangladesh between 2013 and 2016 when a number of secularist and atheist writers, bloggers, and publishers in Bangladesh; foreigners; homosexuals; and religious minorities such as Hindus, Buddhists, Christians and Ahmadis who were seen as having offended Islam and Muhammad were attacked in retaliation, with many killed by Muslim extremists. 

By 2 July 2016, a total of 48 people, including 20 foreign nationals, had been killed in such attacks. These attacks were largely blamed on extremist groups such as Ansarullah Bangla Team and Islamic State of Iraq and Syria. The Bangladeshi government was criticized for its response to the attacks, which included charging and jailing some of the secularist bloggers for allegedly defaming some religious groups; or hurting the religious sentiments of different religious groups; or urging the bloggers to flee overseas. This strategy was seen by some as pandering to hard line elements within Bangladesh's Muslim majority population. About 89% of the population in Bangladesh is Sunni Muslim. The government's eventual crackdown in June 2016 was also criticized for its heavy-handedness, as more than 11,000 people were arrested in a little more than a week (as of 18 June 2016).

Source: Wikipedia — https://en.wikipedia.org/wiki/Washiqur_Rahman$b$, 'en', NULL, $b$Blogger, Journalist$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Farooque$b$, DATE '1948-08-18', DATE '2023-05-15', $b$Akbar Hossain Pathan Dulu (Bengali: আকবর হোসেন পাঠান দুলু; 18 August 1948 – 15 May 2023), known by the stage name Farooque (Bengali: ফারুক), was a Bangladeshi actor, politician, businessman and producer. He was known as 'Mia Bhai' (respected brother) to mass people. He appeared in over 150 films in a career spanning more than five decades. Most of his films were commercially and critically successful. Farooque was one of the most recognizable stars of the classical and golden era of Bangladeshi film industry.

Farooque was the first awardee of the Bangladesh National Film Award for Best Supporting Actor for the film Lathial in 1975 which he declined. In addition, he was awarded the Bangladesh National Film Award for Lifetime Achievement in 2016. As one of the most dominant actors in the Bangladeshi movie scene during the 1970s, 1980s and early 1990s, Farooque is widely considered one of the greatest and influential actors in the history of Bangladeshi cinema.

During Operation Searchlight, on 25 March 1971, he participated in the first resistance of the liberation war in Malitola, Old Dhaka as second in command of their own guerrilla force commanded by 'Nader Gunda'. Later, Farooque succeeded as commander and continued the fighting.

Farooque was a ruling Awami League member of Parliament (MP) for Dhaka-17 since 2018 Bangladeshi general election.

Source: Wikipedia — https://en.wikipedia.org/wiki/Farooque$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Akbar%20Hossain%20Farooque%20%2810%29%20%28cropped%29.jpg?width=640$b$, $b$Television actor, Actor$b$, $b$Dhaka$b$, $b$Singapore$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rama Chowdhury$b$, DATE '1941-10-14', DATE '2018-09-03', $b$Rama Chowdhury (14 October 1936 – 3 September 2018) was a Bangladeshi writer and birangana of Bangladesh Liberation War during 1971. In Bangladesh, she is best known for her autobiographical work "Ekatorer Jononi" ("Mother of 71") which describes the torture committed by Pakistani military during the Bangladesh Liberation War. She was awarded Begum Rokeya Padak by the Government of Bangladesh posthumously in 2019.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rama_Chowdhury$b$, 'en', NULL, $b$Writer$b$, $b$Chattogram District$b$, $b$Chattogram District$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Murtaza Ali$b$, DATE '1902-07-01', DATE '1981-08-09', $b$Syed Murtaza Ali (1 July 1902 – 9 August 1981) was a Bangladeshi writer. He was the elder brother of writer and linguist Syed Mujtaba Ali. He is noted for his works relating to the histories of Chittagong, Sylhet and Jaintia.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Murtaza_Ali$b$, 'en', NULL, $b$Historian, Writer$b$, $b$Sribhumi$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abdul Gafur Hali$b$, DATE '1929-08-06', DATE '2016-12-21', $b$Abdul Gafur Hali (also known as Gafur Hali Maizbhanderi; 6 August 1929 – 21 December 2016) was a Bangladeshi folk lyricist, composer and singer of the Maizbhandari musical tradition. He was the first folk play author to use the Chittagonian language. His works are created mainly in his native language of Chittagong. He was also known by his Sufi name, Gafur Hali Maizbhanderi.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Gafur_Hali$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Abdul%20Gafur%20hali%20pic.jpg?width=640$b$, $b$Lyricist, Composer$b$, $b$Patiya Upazila$b$, $b$Chittagong$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Helena Khan$b$, DATE '1923-03-23', DATE '2019-03-15', $b$Helena Khan (23 March 1927 – 15 March 2019) was a Bangladeshi educationist and writer. She completed her Bachelor of Arts degree from Lady Brabourne College. In her career, she had served in five different government schools.

Source: Wikipedia — https://en.wikipedia.org/wiki/Helena_Khan$b$, 'en', NULL, $b$Writer$b$, NULL, $b$Fayetteville$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rafiqul Islam$b$, DATE '1934-01-01', DATE '2021-11-30', $b$Rafiqul Islam (1 January 1934 – 30 November 2021) was a Bangladeshi educationist, scholar, writer, linguist and cultural activist. He served at the Bangla Academy as a president (2021) and a director general (2001). He was inducted as a National Professor by the Government of Bangladesh in July 2018. He was a vice-chancellor (2007–2011), professor emeritus and adviser to the Centre for Bangla Studies of the University of Liberal Arts Bangladesh (ULAB). He served as the chairman of the Nazrul Institute Trustee Board. He was awarded Ekushey Padak in 2001 and Independence Day Award in 2012 by the Government of Bangladesh.

Islam's notable books include Nazrul Nirdeshika, Bhashtottya, An Introduction to Colloquial Bengali, Bangladesher Swadhinota Sangram, Bhasha Andolan O Shahid Minar, Dhakar Kotha, Bhasha Andolan o Muktijhuddher Shahitya, Swadhinotar Sangrame Dhaka Biswabidyalaya, and Dhaka Biswabidyalayar Ashi Bosor.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rafiqul_Islam_(educationist)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Professor%20Dr.%20Rafiqul%20Islam%20in%20Dhaka%202019%20%281%29.jpg?width=640$b$, $b$Linguist, Writer$b$, $b$Chandpur District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Halima Khatun$b$, DATE '1933-08-25', DATE '2018-07-03', $b$Halima Khatun (25 August 1933 – 3 July 2018) was a Bangladeshi activist, writer and academic. She took part in the Bengali language movement in 1952 along with other activists including Rawshan Ara Bachchu. She was a recipient of the Bangla Academy Literary Award in 1981 and posthumously received the Ekushey Padak award in 2019.

Source: Wikipedia — https://en.wikipedia.org/wiki/Halima_Khatun$b$, 'en', NULL, $b$Academic, Writer$b$, $b$Bagerhat Sadar Upazila$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ashim Saha$b$, DATE '1949-02-20', DATE '2024-06-18', $b$Asim Saha (20 February 1949 – 18 June 2024) was a Bangladeshi poet and novelist. He received Bangla Academy Literary Award in 2011 for his contributions to poetry. In recognition of his contribution to Bengali language and literature, the government of Bangladesh awarded him the country's second-highest civilian award Ekushey Padak in 2019.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ashim_Saha$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Ashim%20Saha%20picture.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Netrokona District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Chitranibha Chowdhury$b$, DATE '1913-11-27', DATE '1999-11-09', $b$Chitranibha Chowdhury (27 November 1913 – 9 November 1999) was a twentieth-century Indian artist, a member of the Bengal School of Art, and one of the first female painters in Bengal. She created over a thousand artworks, including landscapes, still lifes, decorative art, murals, and portraits. She was a Nandalal Bose student and the first female painting teacher in Kala Bhavana, Shantiniketan. Her real name Nibhanani Bose was changed to Chitranibha Bose by Rabindranath Tagore.

Source: Wikipedia — https://en.wikipedia.org/wiki/Chitranibha_Chowdhury$b$, 'en', NULL, $b$Painter, Artist$b$, $b$Jiaganj Azimganj$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ahmed Rajib Haider$b$, NULL, DATE '2013-02-15', $b$Ahmed Rajib Haider (died 15 February 2013) was a Bangladeshi atheist blogger. He used to blog in the blogging communities namely somewhereinblog.net, amarblog.com and nagorikblog.com and used the pseudonym Thaba Baba.

On 15 February 2013, after comments he posted online about religious fundamentalism, he was hacked to death by machete-wielding terrorists from a militant group named Ansarullah Bangla Team. He was the first protester killed during the Shahbag movement.

An architect by profession, Haider's blog was among those that ignited the 2013 Shahbag protests. The protesters were seeking trials for the perpetrators of the mass killings during the Bangladesh Liberation War of 1971, a move that was widely seen as aimed at radical Islamists. The protests were opposed by Islamic groups, who organised counter marches under the banner of a newly formed group called Hefazat-e-Islam Bangladesh.

On 30 December 2015, after almost three years, two members of the Ansarullah Bangla Team, Md Faisal Bin Nayem and Redwanul Azad Rana, were found guilty of murder and sentenced to death. Faisal, the court said, was the one who attacked Haider with a meat cleaver. Rana had absconded and was sentenced in absentia. Another member of the outlawed outfit, Maksudul Hasan was also found guilty of murder and given a life sentence. Six other members of ABT, including firebrand leader Mufti Jasim Uddin Rahmani, received jail terms of five to ten years.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ahmed_Rajib_Haider$b$, 'en', NULL, $b$Architect$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ibrahim Saber$b$, NULL, DATE '2019-06-19', $b$Ibrahim Saber (1945 – 19 June 2019) was a Bangladeshi field hockey player and captain of Bangladesh men's national field hockey team. In recognition of his contribution in sports, he won the National Sports Awards in 1997.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ibrahim_Saber$b$, 'en', NULL, $b$Cricketer, Field hockey player, Association football player, Basketball player$b$, $b$Bengal Presidency$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Hiranmay Sen Gupta$b$, DATE '1934-08-01', DATE '2022-01-08', $b$Hiranmay Sen Gupta, Bengali: হিরন্ময় সেন গুপ্ত, (1 August 1934 – 8 January 2022) was a Bangladeshi physicist who specialised in nuclear physics. In a career spanning five decades he published over 200 research papers and was made a fellow of Bangladesh Academy of Sciences in 1977.

Source: Wikipedia — https://en.wikipedia.org/wiki/Hiranmay_Sen_Gupta$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/H.M.%20SEN%20GUPTA.jpg?width=640$b$, $b$Theoretical physicist, Nuclear physicist, Physicist$b$, $b$Barishal$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$A.Z.M. Enayetullah Khan$b$, DATE '1939-05-25', DATE '2005-11-10', $b$Abu Zafar Mohammad Enayetullah Khan (known as Enayetullah Khan; 25 May 1939 – 10 November 2005) was a Bangladeshi journalist and government minister. He founded the weekly newspaper Holiday and the daily newspaper New Age. He served in Ziaur Rahman's cabinet, first as minister of land administration and land reform from December 1977 to June 1978, and then as minister of petroleum and natural resources from July 1978 to October 1978.

Md. Shaheduzzaman had remarked him as one of the best political writers in South-East Asia.

He was president of the Jatiya Press Club and the Dhaka Club.

Source: Wikipedia — https://en.wikipedia.org/wiki/A.Z.M._Enayetullah_Khan$b$, 'en', NULL, $b$Journalist, Politician$b$, $b$Mymensingh$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Panna Kaiser$b$, DATE '1950-05-25', DATE '2023-08-04', $b$Panna Kaiser (25 May 1950 – 4 August 2023) was a Bangladesh Awami League politician and a member of Jatiya Sangsad selected for the women's reserved seats during 1996–2001. She was awarded 2021 Bangla Academy Literary Award in the research on liberation war category.

