INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khalekdad Chowdhury$b$, DATE '1907-02-02', DATE '1985-10-16', $b$Khalekdad Chowdhury (Bengali: খালেকদাদ চৌধুরী; 2 February 1907 – 16 October 1985), also known by pen names Shahadat Chowdhury and Atashbaz, is a reputed Bangladeshi writer, playwright and novelist. In recognition of his contribution to Bengali language and literature, the government of Bangladesh posthumously awarded him the country's second highest civilian award Ekushey Padak in 2018.

