INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sufia Khatun$b$, NULL, DATE '2023-01-07', $b$Sufia Khatun (Bengali: সুফিয়া খাতুন) (May 1922 – 7 January 2023) was a Bangladeshi author and social activist. She won the Bangla Academy Literary Award in 2021.

