INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Qayyum Chowdhury$b$, DATE '1932-03-09', DATE '2014-11-30', $b$Qayyum Chowdhury (9 March 1932 – 30 November 2014) was a Bangladeshi painter. Along with Zainul Abedin, Quamrul Hassan and Safiuddin Ahmed, he is considered as a first generation artist of Bangladesh. He was awarded the Ekushey Padak in 1984 and the Independence Day Award in 2014 by the Government of Bangladesh.

