INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Qazi Anwar Hussain$b$, DATE '1936-07-19', DATE '2022-01-19', $b$Qazi Anwar Hussain (19 July 1936 – 19 January 2022) was a Bangladeshi writer of spy thrillers, detective novels, and adventure-based literature, many of which were adaptations or heavily influenced by foreign works.

Source: Wikipedia — https://en.wikipedia.org/wiki/Qazi_Anwar_Hussain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Qazi%20Anwar%20Hussain.jpg?width=640$b$, $b$Writer$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rafiq Azad$b$, NULL, DATE '2016-03-12', $b$Rafiq Azad (born Rafiqul Islam Khan; February 14, 1941 – March 12, 2016) was a Bangladeshi poet, editor and writer. He is credited with 45 collections of poetry including Prakriti O Premer Kabita, Asambhaber Paye, Sahasra Sundar, Haturir Nichae Jiban, Khub Beshi Durea Noy, Khamakaro Bahaman Hey Udar Amiyo Batas and others. He is most well known for his poem "Bhaat De Haramjada" (Give me rice, bastard) which was written during the famine of 1974. The poet participated in the war against Pakistani forces in the Bangladesh Liberation War of 1971 and was awarded ‘Notable Freedom Fighter Award' in 1997. He received Bangla Academy Literary Award in 1984 and national award Ekushey Padak in 2013 for his contribution to Bangla language and literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Rafiq_Azad$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Tangail$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nurul Islam$b$, NULL, DATE '2023-05-09', $b$Nurul Islam (1 April 1929 – 9 May 2023) was a Bangladeshi economist, philanthropist, and politician. Islam is famous for his contributions during the independence war of Bangladesh, as well as for his pivotal role in the economy and foreign affairs during the 1970s as cabinet minister and deputy chairman of the Planning Commission. He was the closest advisor to, and confidant of, Sheikh Mujibur Rahman (first Prime Minister of Bangladesh) throughout the 1960s and until the Prime Minister's assassination in 1975.

Islam is responsible for establishing Bangladesh's economy, financial system, and trade relationships; his leadership laid the foundations for Bangladesh's unprecedented economic growth over five decades. Islam has mentored many Bengali power players (including Prime Minister Fakhruddin Ahmed and Nobel Peace Prize Winner Muhammad Yunus). Today, the Islam family is prominent in South Asian business, with significant holdings across manufacturing, construction, and financial services; the companies they own employ more than 60,000 workers. The Islam family is active in philanthropy, particularly in support of education, diabetes research, and women's rights. They founded Shakti Foundation, Bangladesh's third largest charity organization, as well as several urban-area hospitals and schools.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nurul_Islam_(economist)$b$, 'en', NULL, $b$University teacher, Economist, Politician$b$, $b$Chittagong$b$, $b$Washington, D.C.$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mahbub Ul Alam Choudhury$b$, DATE '1927-11-07', DATE '2007-12-23', $b$Mahbub Ul Alam Choudhury (7 November 1927 – 23 December 2007) was a Bangladeshi poet, journalist, and activist in the Bengali language movement. He wrote the first poem on the Bengali Language Movement. He was awarded the Ekushey Padak in 2009 by the government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mahbub_Ul_Alam_Choudhury$b$, 'en', NULL, $b$Poet$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Muhammad Qudrat-i-Khuda$b$, NULL, DATE '1977-11-03', $b$Muhammad Qudrat-A-Khuda (1 December 1900 – 3 November 1977) was a Bangladeshi organic chemist, educationist and writer. He is most notable for publishing Qudrat-a-Khuda Education Commission Report in 1973 as a chairman of the National Education Commission of the newly independent country of Bangladesh. He founded the Bangladesh Council of Scientific and Industrial Research (BCSIR).

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Qudrat-i-Khuda$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Qudrat%20Khuda.jpg?width=640$b$, $b$Chemist, Writer$b$, $b$Margram$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ahmed Ali$b$, DATE '1932-03-01', DATE '2020-01-11', $b$Ahmed Ali (1 March 1932 – 11 January 2020) was a Bangladeshi politician and lawyer belonging to Bangladesh Awami League. He was elected as a member of the East Pakistan Provincial Assembly from Comilla-5. Later, he was appointed as a member of the Constituent Assembly of Bangladesh. He took part in the Language Movement. He was an organizer of the Liberation War of Bangladesh too.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ahmed_Ali_(Bangladeshi_politician)$b$, 'en', NULL, $b$Politician, Lawyer, Writer$b$, $b$Nabinagar Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kazi Abdul Baset$b$, DATE '1935-12-04', DATE '2002-05-23', $b$Kazi Abdul Baset (December 4, 1935 – May 23, 2002) was a Bangladeshi painter and art teacher. He was awarded Ekushey Padak in 1991 by the Government of Bangladesh.

