INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Muhammad Shamsul Huq$b$, DATE '1912-10-12', DATE '2006-02-23', $b$Muhammad Shamsul Huq (12 October 1912 – 23 February 2006) was a Bangladeshi politician and educator. He served as an education minister in erstwhile East Pakistan, and became the minister of foreign affairs six years after the independence of Bangladesh. Shamsul Huq also served as vice-chancellor in both the University of Dhaka and University of Rajshahi. He was awarded the Ekushey Padak in 2003 by the government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Muhammad_Shamsul_Huq$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Shamsul%20Haque%20Brussels%201979.jpg?width=640$b$, $b$Academic, Writer$b$, $b$Laksam Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Benajir Ahmed$b$, NULL, DATE '1983-02-12', $b$Benajir Ahmed (c. 1903 – 12 February 1983) was a Bangladeshi poet and writer. He was awarded Bangla Academy Literary Award in 1964 and Ekushey Padak in 1979 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Benajir_Ahmed$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Narayanganj District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kuntal Chandra$b$, DATE '1984-11-08', DATE '2012-12-03', $b$Kuntal Chandra (8 November 1984 – 3 December 2012) was a cricketer from Bangladesh.

Chandra was a right-handed batsman and wicket keeper sometimes known by his nickname Papon. He studied at Bangladesh Krira Shikkha Protishtan. After playing for Bangladesh Under-19s in 2000, he made his debut for Chittagong Division in 2004–2005 against Rajshahi Division, taking five catches and scoring 71 and 33. Despite this promising beginning he played only two more first-class matches, and those not until the 2007–2008 season. He also played in two List A one-day matches in 2005.

Source: Wikipedia — https://en.wikipedia.org/wiki/Kuntal_Chandra$b$, 'en', NULL, $b$Cricketer$b$, $b$Tangail$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Jatin Sarker$b$, DATE '1936-08-13', DATE '2025-08-13', $b$Jatin Sarker (18 August 1936 – 13 August 2025) was a Bangladeshi Bengali intellectual, researcher, and biographer of Bangladesh. He was awarded the Bangla Academy Literary Award in 2008 for research and essays and the Independence Day Award in 2010 for education. As of September 2021, he had published 35 books.

Source: Wikipedia — https://en.wikipedia.org/wiki/Jatin_Sarker$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Jatin%20Sarker%202006.JPG?width=640$b$, $b$Writer$b$, $b$Netrokona District$b$, $b$Mymensingh$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Dilwar Khan$b$, DATE '1937-01-01', DATE '2013-10-10', $b$Dilwar Khan (1 January 1937 – 10 October 2013) was a Bangladeshi poet. Known as Gono Manusher Kobi (poet of the mass people), he was awarded Bangla Academy Literary Award in 1980 and Ekushey Padak in 2008 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Dilwar_Khan$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Kabi%20Dilwar%20And%20wife.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Sylhet$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Gaziul Haque$b$, DATE '1929-02-13', DATE '2009-06-17', $b$Abu Naser Muhammad Gaziul Haque (13 February 1929 – 17 June 2009) was a language activist and an activist leader during the Bengali language movement.

Source: Wikipedia — https://en.wikipedia.org/wiki/Gaziul_Haque$b$, 'en', NULL, $b$Poet$b$, $b$Feni District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Humayun Faridi$b$, DATE '1952-05-29', DATE '2012-02-13', $b$Humayun Kamrul Islam, better known as Humayun Faridi (Bengali: হুমায়ুন ফরীদি, romanized: Humayon Foridi; 29 May 1952 – 13 February 2012) was a Bangladeshi actor. He worked in television dramas, movies and theatre plays. He won the Bangladesh National Film Award for Best Actor for his lead role in the film Matritto (2004). He was awarded Ekushey Padak posthumously in 2018 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Humayun_Faridi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Humayun%20Faridi%20%28cropped%29.gif?width=640$b$, $b$Television actor, Actor$b$, $b$Dhaka$b$, $b$Dhanmondi Thana$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Asad Chowdhury$b$, DATE '1943-02-11', DATE '2023-10-05', $b$Asad Chowdhury (11 February 1943 – 5 October 2023) was a Bangladeshi poet, writer, translator, radio, television personality, journalist, and cultural activist. He was awarded the Ekushey Padak in 2013 and the Bangla Academy Literary Award in 1987.

