INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Bande Ali Mia$b$, DATE '1906-01-17', DATE '1979-06-27', $b$Bande Ali Mia (17 January 1906 – 27 June 1979) was a Bangladeshi poet, lyricist, novelist, dramatist, essayist, children's writer, and journalist. He was awarded the Bangla Academy Literary Award in 1962 and the Ekushey Padak in 1988.

Source: Wikipedia — https://en.wikipedia.org/wiki/Bande_Ali_Mia$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Pabna$b$, $b$Rajshahi$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Bashir Ahmad$b$, DATE '1940-04-12', DATE '2014-04-19', $b$Bashir Ahmed (11 November 1939 – 19 April 2014) was a Pakistani-Bangladeshi playback singer, lyricist, and musician who started his career from Lollywood in the 1960s. He is known for his playback songs in the films Talash (1963) and Darshan (1967). He was awarded Ekushey Padak in 2005 by the Government of Bangladesh and Bangladesh National Film Award for Best Male Playback Singer for his performance in the film Kokhono Megh Kokhono Bristi (2003). He is known as East Pakistan's Ahmed Rushdi because his singing style is inspired by him.

Source: Wikipedia — https://en.wikipedia.org/wiki/Bashir_Ahmad_(singer)$b$, 'en', NULL, $b$Singer$b$, $b$Kolkata$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abdul Mannan Syed$b$, NULL, DATE '2010-09-05', $b$Abdul Mannan Syed (3 August 1943 – 5 September 2010) was a Bangladeshi poet, academic, and critic. He is known for his considerable research works on Kazi Nazrul Islam, Jibanananda Das, Farrukh Ahmad, Syed Waliullah, Manik Bandyopadhyay, Bishnu De, Samar Sen, Roquiah Sakhawat Hossain, Abdul Ghani Hazari, Muhammad Wajed Ali, and Prabodh Chandra Sen. From 2002 to 2004, he held the position of executive director of the Nazrul Institute.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Mannan_Syed$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Abdul-Mannan-Syed-2006.jpg?width=640$b$, $b$Philologist, Writer$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abid Azad$b$, DATE '1952-11-16', DATE '2005-03-22', $b$Abid Azad (16 November 1952 – 22 March 2005) was an eminent Bangladeshi poet, critic and literary editor. Azad was the author of 19 books of poetry including Ghaser Ghatana (1976), Amar Mon Kemon Kore (1980), Banotaruder Marma (1982), and Shiter Rachanabali (1983).

Source: Wikipedia — https://en.wikipedia.org/wiki/Abid_Azad$b$, 'en', NULL, $b$Poet$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abu Zafar Obaidullah$b$, DATE '1934-02-08', DATE '2001-03-19', $b$Abu Zafar Obaidullah (Bengali pronunciation: [abu d͡ʒafoɾ obae̯d̪ulːaʱ]; 8 February 1934 – 19 March 2001) was a Bangladeshi poet and civil servant. Two of his long poems, Aami-Kingbodontir-Kathaa Bolchi and Bristi O Shahosi Purush-er Jonyo Prarthona, have become famous since their first publication in the late 1970s.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abu_Zafar_Obaidullah$b$, 'en', NULL, $b$Poet, Writer$b$, $b$Barishal$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Alamgir Kabir$b$, DATE '1938-12-26', DATE '1989-01-20', $b$Alamgir Kabir (26 December 1938 – 20 January 1989) was a Bangladeshi film director and cultural activist. Three of his feature films are featured in the "Top 10 Bangladeshi Films" list by British Film Institute.

Kabir was awarded Independence Day Award posthumously in 2010 for his contribution to the Bangladeshi culture.

Source: Wikipedia — https://en.wikipedia.org/wiki/Alamgir_Kabir_(film_maker)$b$, 'en', NULL, $b$Film director, Screenwriter$b$, $b$Rangamati$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Dilara Hashem$b$, DATE '1936-08-21', DATE '2022-03-19', $b$Dilara Hashem (née Khanom, 25 August 1935 – 19 March 2022) was a Bangladeshi author and novelist. She was among the first Bengali writers to receive Bangla Academy Literary Award in 1976 for her contribution in literature. Her notable works include Ekada Ebang Ananta, Stabdhatar Kane Kane, Amlakir Mou, Badami Bikeler Galpa, Kaktaliya, Shangkha Karat, Anukta Padabali, Sadar Andar and Setu.

Source: Wikipedia — https://en.wikipedia.org/wiki/Dilara_Hashem$b$, 'en', NULL, $b$Journalist, Writer$b$, $b$Jashore$b$, $b$Maryland$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Khan Sarwar Murshid$b$, DATE '1924-07-01', DATE '2012-12-08', $b$Khan Sarwar Murshid (Bengali: খাঁন সারওয়ার মুরশিদ; 1 July 1924 – 8 December 2012) was a Bangladeshi educationist and diplomat.

Source: Wikipedia — https://en.wikipedia.org/wiki/Khan_Sarwar_Murshid$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/KSMurhed-2010-FLC.jpg?width=640$b$, $b$Scholar of English, Academic, University teacher, Diplomat$b$, $b$Brahmanbaria District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Chashi Nazrul Islam$b$, DATE '1941-10-23', DATE '2015-01-11', $b$Chashi Nazrul Islam (11 October 1941 – 11 January 2015) was a Bangladeshi film director and producer. He won the Bangladesh National Film Award for Best Director twice for the films Shuvoda in 1986 and Hangor Nodi Grenade in 1997. He was awarded the Ekushey Padak in 2004 by the government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Chashi_Nazrul_Islam$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Zafor%20Firoze%20and%20Chashi.jpg?width=640$b$, $b$Film director$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kalim Sharafi$b$, DATE '1924-05-08', DATE '2010-11-02', $b$Kalim Sharafi (8 May 1924 – 2 November 2010) was a Bangladeshi Rabindra Sangeet singer. He joined at Indian independence movement. He gave his ideas in several publications regarding politics, culture, and Tagore. He is regarded as one of the best Rabindra Sangeet singers in the subcontinent.

Source: Wikipedia — https://en.wikipedia.org/wiki/Kalim_Sharafi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Jangi%20receiving%20an%20award%20from%20Kalim%20Sharafi.jpg?width=640$b$, $b$Film director, Singer$b$, $b$Birbhum district$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nitun Kundu$b$, DATE '1935-12-03', DATE '2006-09-15', $b$Nitya Gopal Kundu (3 December 1935 – 15 September 2006) was a Bangladeshi artist, sculptor and entrepreneur. Kundu played an important role during the liberation war of Bangladesh in 1971. He founded the furniture company Otobi.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nitun_Kundu$b$, 'en', NULL, $b$Sculptor, Painter, Businessperson$b$, $b$Dinajpur$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sajjadul Hasan$b$, DATE '1978-05-25', DATE '2007-03-16', $b$Mohammad Sajjadul Hasan (25 September 1978 – 16 March 2007) was a Bangladeshi first-class cricketer.

Nicknamed 'Setu', he was an opening or top-order batsman for Khulna Division. Hasan was the leading runscorer in the 2002–03 Bangladeshi domestic season with 447 runs at 40.63.

He captained Khulna Division on two occasions in the first-class format, against Rajshahi Division and Chittagong Division, but lost both games. He also has a stumping to his name, claimed during Khulna Division's match against Chittagong Division in 2005.

He died aged 28 in a road accident alongside his Khulna Division teammate and Bangladesh Test cricketer Manjural Islam Rana. In his 50-game career he made 2443 runs at 28.08 with 3 hundreds.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sajjadul_Hasan$b$, 'en', NULL, $b$Cricketer$b$, $b$Khulna$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kazi M. Badruddoza$b$, DATE '1927-01-01', DATE '2023-08-30', $b$Kazi M. Badruddoza (1 January 1927 – 30 August 2023) was a Bangladeshi agronomist who is credited with using Agricultural Genetics and Plant Pathology to increase agricultural production in Bangladesh, contributing to greater self-sufficiency in staple cereal crops. He is known as the Father of Modern Agriculture in Bangladesh and the only National Emeritus Scientist of Bangladesh. He was one of the early leaders of the global team of the green revolution for his role in development of high yielding wheat, rice and maize varieties. For his work in Agricultural genetics, Badruddoza was awarded numerous honors, including the Independence Day award, the highest civilian award of Bangladesh. Prior to creation of Bangladesh as an independent state, he was also awarded the Tamgha-e-Imtiaz, a state organized civil award, in former West Pakistan, as well as the Tamgha-e-Pakistan. In addition, he is credited with the genetic engineering for the highly nutritious and large variety of guava, the Kazi Guava. In his honor, the genus of fungus, Kaziboletus. in the family Boletaceae, discovered in Bangladesh, was named after him.

Source: Wikipedia — https://en.wikipedia.org/wiki/Kazi_M._Badruddoza$b$, 'en', NULL, $b$Scientist$b$, $b$Bogura District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sheikh Salahuddin$b$, DATE '1969-02-10', DATE '2013-10-29', $b$Sheikh Salahuddin Ahmed (10 February 1969 – 29 October 2013) was a Bangladeshi international cricketer.

He was born in Rajapur, Khulna, and played in six One Day Internationals (ODIs) in 1997. He continued to play first-class cricket for Khulna Division until 2006.

Salahuddin died in October 2013 from a cardiac arrest. A minute of silence was held in his memory before the ODI between Bangladesh and New Zealand at Dhaka later on the same day.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sheikh_Salahuddin_(cricketer)$b$, 'en', NULL, $b$Cricketer$b$, $b$Rajapur Village$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sanjeeb Choudhury$b$, DATE '1962-12-25', DATE '2007-11-19', $b$Sanjeeb Choudhury (25 December 1964 – 19 November 2007) was a Bangladeshi singer-songwriter, writer, journalist and political activist. He was one of the two leading members of the Bengali band Dalchhut with Bappa Mazumder and was the composer for Dalchhut's four albums. He was also a journalist and worked for the newspaper Ajker Kagoj, Bhorer Kagoj, and Jaijaidin. He was an activist during the mass upsurge against the autocratic regime of Hossain Mohammad Ershad.

Source: Wikipedia — https://en.wikipedia.org/wiki/Sanjeeb_Choudhury$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Concert%20of%20Dalchhut%20at%20AIUB%20by%20Farsad4%20%28cropped%29.JPG?width=640$b$, $b$Journalist, Author, Singer$b$, $b$Baniachang Upazila$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shafin Ahmed$b$, DATE '1961-02-14', DATE '2024-07-24', $b$Shafin Ahmed (14 February 1961 – 24 July 2024) was a Bangladeshi rock bassist, singer-songwriter, record producer and politician. He was the lead singer, songwriter and bassist for the Bangladeshi rock band Miles, where he and his elder brother Hamin Ahmed joined in 1979 and led the band.

Born in the city of Kolkata, Shafin was the youngest son of Bangladeshi classical music singer Kamal Dasgupta and Bangladeshi singer Firoza Begum. Their family was traditionally a musical family. He started his musical career at the age of 9. They moved to Dhaka in the late 1960s. He was exposed to rock and roll music in the late 1970s, when he went to London for higher education. He joined Miles in 1979, first as an acoustic guitarist, and later lead singer and bassist in 1991 when many of the past members had left and Miles reestablished themselves in the 1990s Bangla rock music scene.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shafin_Ahmed$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Shafin%20Ahmed%20%28cropped%29.jpg?width=640$b$, $b$Singer$b$, $b$Kolkata$b$, $b$Woodbridge$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shah A M S Kibria$b$, DATE '1931-05-01', DATE '2005-01-27', $b$Shah Abu Muhammad Shamsul Kibria (Bengali: শাহ্‌ আবু মুহাম্মদ শামসুল কিবরিয়া; 1 May 1931 – 27 January 2005), known as SAMS Kibria or Shams Kibria, was a Bangladeshi economist, diplomat and politician.

Joining the Foreign Service of Pakistan in 1954, Kibria served in a number of diplomatic missions for Pakistan. In 1971, at the height of the Bangladesh Liberation War, Kibria, an ethnic Sylheti, dissociated himself from the Pakistani foreign service and declared allegiance to the Mujibnagar government. After the independence of Bangladesh, he served as the Director General of the Political Affairs department of the Ministry of Foreign Affairs of Bangladesh and twice as the foreign secretary of Bangladesh. Between 1981 and 1992, Kibria was the executive secretary of the UN Economic and Social Commission for Asia and the Pacific (ESCAP).

Kibria joined the Awami League in 1992. He served as the minister of finance of the Bangladesh government led by Sheikh Hasina from 1996 to 2001. In the 2001 general election of Bangladesh, he was elected a member of the parliament from his constituency Habiganj-3 in 2001 until his assassination in 2005.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shah_A_M_S_Kibria$b$, 'en', NULL, $b$Diplomat, Economist, Politician$b$, $b$Sylhet District$b$, $b$Habiganj District$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mohammad Nurul Islam$b$, NULL, DATE '2007-12-22', $b$Mohammad Nurul Islam (c. 1924 – 22 December 2007) was a Bangladeshi economist who served as the third Governor of Bangladesh Bank, country's central bank, from 1976 to 1987.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mohammad_Nurul_Islam$b$, 'en', NULL, $b$Economist$b$, NULL, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shahed Ali$b$, DATE '1925-05-24', DATE '2001-11-07', $b$Shahed Ali (Bengali: শাহেদ আলী; 24 May 1925 – 6 November 2001) was a Bangladeshi litterateur and cultural activist. Aside from being an educationist and his journalism, he was one of the founders of the nationwide Tamaddun Majlish which initiated the Bengali language movement. He edited multiple magazines, was the founding secretary of the Islamic Academy (now Islamic Foundation Bangladesh), and is best known for his magnum opus, the short story Jibrailer Dana (Gabriel's Wings).

Source: Wikipedia — https://en.wikipedia.org/wiki/Shahed_Ali_(writer)$b$, 'en', NULL, $b$Writer$b$, $b$Sunamganj District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shahidul Zahir$b$, DATE '1955-09-11', DATE '2008-03-23', $b$Shahidul Zahir (Bengali: শহীদুল জহির; born as Mohammad Shaheedul Haque, 11 September 1953 – 23 March 2008) was a Bangladeshi novelist, short story writer, and government bureaucrat. He is known for his unique practice of magical realism in modern Bengali literature. His novels and short stories have been noted for their originality of language and narrative technique. He contributed to Bengali fiction a distinct style, known as the "Shahidul Zahiriya".

He published four novels and three story collections. Abu Ibrahimer Mirtu (Abu Ibrahim's Death, 2009) is one of his notable novels, which won the Prothom Alo Book of the Year 1415 award in 2010. Also, the novels Jibon O Rajnaitik Bastobota (Life and Political Reality, 1988), Se Ratey Purnima Chilo (That Night Was the Full Moon, 1995), and Mukher Dike Dekhi (Looking to the Face, 2006) are considered to be his major contributions to Bengali literature. He has added a new dimension to Bengali short stories. His notable collections of stories are Parapar (Crossing, 1985), Dumur-kheko Manush O Annanya Galpo (Fig-Eating People and Other Stories, 1999), and Dolu Nadir Hawa O Annanya Galpo (The Wind of the Dolu River and Other Stories, 2004).

Source: Wikipedia — https://en.wikipedia.org/wiki/Shahidul_Zahir$b$, 'en', NULL, $b$Secretary of the Government, Short story writer, Novelist, Translator$b$, $b$Narinda$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Shamsuddin Abul Kalam$b$, NULL, DATE '1997-01-10', $b$Shamsuddin Abul Kalam (1926 – 10 January 1997) was an author of Bengali literature from Bangladesh. His most notable work is a novel, Kashboner Konya (1954). He was awarded the 1964 Bangla Academy Literary Award in the novel category. After his migration to Italy in 1959, he also worked on their film industry.

Source: Wikipedia — https://en.wikipedia.org/wiki/Shamsuddin_Abul_Kalam$b$, 'en', NULL, $b$Writer$b$, $b$Barishal$b$, $b$Rome$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Subir Nandi$b$, DATE '1953-11-19', DATE '2019-05-07', $b$Subir Nandi (19 November 1953 – 7 May 2019) was a Bangladeshi musician. He won Bangladesh National Film Award for Best Male Playback Singer five times for his performance in the films Mahanayak (1984), Shuvoda (1986), Srabon Megher Din (1999), Megher Pore Megh (2004) and Mohua Sundori (2015). He was awarded Ekushey Padak in 2019 by the government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Subir_Nandi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Subir%20Nandi%2C%2024%20July%202017%20%28cropped%29.jpg?width=640$b$, $b$Singer$b$, $b$Sylhet$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Jahangir$b$, DATE '1935-01-02', DATE '2018-12-29', $b$Syed Jahangir (2 January 1935 – 29 December 2018) was a Bangladeshi painter. He was awarded Ekushey Padak by the Government of Bangladesh in 1985. He served as the department head of the Arts Faculty at Shilpakala Academy in 1977. His notable paintings include Attmar Ujjibon, Ullas, Dhoni, Ojana-Oneshya and Osoni-Sangket.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Jahangir$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Syed%20Jahangir%202016.jpg?width=640$b$, $b$Painter$b$, $b$Satkhira District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Syed Shamsul Haque$b$, DATE '1935-12-27', DATE '2016-09-27', $b$Syed Shamsul Haq (Bengali: সৈয়দ শামসুল হক, pronounced [soi̯̯ɔd̪ ʃamsul ɦɔk]; 27 December 1935 – 27 September 2016) was a Bangladeshi writer. He was awarded Bangla Academy Literary Award in 1966 (the youngest among all to receive it), Ekushey Padak in 1984 and Independence Day Award in 2000 by the Government of Bangladesh for his contributions to Bangla literature. His notable works include "Payer Awaj Pawa Jai", "Nishiddho Loban", "Khelaram Khele Ja", "Neel Dongshon" and "Mrigoya". He is known as "Sabyasachi" for his contribution to every branch of litareture.

Source: Wikipedia — https://en.wikipedia.org/wiki/Syed_Shamsul_Haque$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Syed%20Shamsul%20Haque.png?width=640$b$, $b$Poet, Writer$b$, $b$Kurigram District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Tofael Ahmad$b$, DATE '1919-02-22', DATE '2002-03-28', $b$Tofail Ahmed (22 February 1919 – 28 March 2002) was a well-known Bangladeshi researcher of Folk Art. He was also a collector of Folk artifacts and has authored several books on Bangladeshi Folk arts and Crafts. He was awarded the Shilu Abed Karushilpa Award for his contribution to Folk Arts and Craft in 1998. He was also elected as an honorary fellow of the Bangla Academy in 2001.

Source: Wikipedia — https://en.wikipedia.org/wiki/Tofael_Ahmad_(folklorist)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Tofail%20ahmed.JPG?width=640$b$, $b$Art collector, Academic, Pedagogue, Artist$b$, $b$Lakshmipur District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Rawshan Jamil$b$, NULL, DATE '2002-05-14', $b$Rawshan Jamil (8 May 1931 – 14 May 2002) was a Bangladeshi actress and dancer. She was awarded the Ekushey Padak in the dance category in 1995 and the Bangladesh National Film Award for Best Supporting Actress for her role in Noyonmoni (1976).

Source: Wikipedia — https://en.wikipedia.org/wiki/Rawshan_Jamil$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Rawshan%20Jamil%20%28cropped%29.jpg?width=640$b$, $b$Actor$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Atia Islam Anne$b$, NULL, DATE '2026-07-02', $b$Atia Islam Anne (1962 – 2 July 2026) was a Bangladeshi artist known for her work on women's regrets, needs, despair and frustration and, more broadly, violence against women. Along with artists like Dilara Begum Jolly, Kanak Chanpa Chakma, and Fareha Zeba, Anne is part of a movement of women artists whose feminist work became more popular during the 1990s in Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Atia_Islam_Anne$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Atia%20Islam%20Anne.png?width=640$b$, $b$Painter$b$, $b$Dhaka$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$AKM Nurul Islam$b$, NULL, DATE '2006-07-01', $b$AKM Nurul Islam (27 October 1928 – 1 July 2006) was a Bangladeshi botanist and academician. He was selected as the National Professor of Bangladesh in 2006. He was a Fellow of Bangladesh Academy of Sciences since 1980 and Bangladesh Botanical Society since 1997.

Source: Wikipedia — https://en.wikipedia.org/wiki/AKM_Nurul_Islam_(botanist)$b$, 'en', NULL, $b$Botanist, Botanical collector$b$, $b$Natore District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Mahbub Talukdar$b$, DATE '1942-02-13', DATE '2022-08-24', $b$Mahbub Talukdar (13 February 1942 – 24 August 2022) was a Bangladeshi poet, writer, civil servant, and one of the Election Commissioners of Bangladesh. He was awarded Bangla Academy Literary Award in 2012 for his contribution in juvenile literature. He was a Freedom Fighter and joined the exiled government in 1971.

Source: Wikipedia — https://en.wikipedia.org/wiki/Mahbub_Talukdar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mahbub%20Talukder%202010.jpg?width=640$b$, $b$Poet, Writer$b$, $b$Purbadhala Upazila$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Monem Munna$b$, DATE '1966-06-09', DATE '2005-02-12', $b$Mohammad Monem Munna (Bengali: মোনেম মুন্না; 9 June 1966 – 12 February 2005) was a Bangladeshi footballer who mainly played as a center back. He is often regarded as the best defender that ever played for Bangladesh. He was well known by his nickname "The King-Back".

Source: Wikipedia — https://en.wikipedia.org/wiki/Monem_Munna$b$, 'en', NULL, $b$Association football player$b$, $b$Dhaka$b$, $b$Dhaka$b$);
