Source: Wikipedia — https://en.wikipedia.org/wiki/Momtaz_Begum_(professor)$b$, 'en', NULL, $b$University teacher, Politician$b$, $b$Cumilla$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Zafar Iqbal$b$, DATE '1950-09-25', DATE '1991-04-27', $b$Zafar Iqbal (born 25 September 1950 – died 8 January 1992 ) was a Bangladeshi actor, singer and freedom fighter. He acted in 150 films. Singer Shahnaz Rahmatullah and music composer Anwar Parvez were his siblings.

