INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Amol Bose$b$, NULL, DATE '2012-01-23', $b$Amal Bose (born Amalendu Bose (Bengali: অমল বোস); 1943 – 23 January 2012) was a Bangladeshi actor who appeared in theater, television and radio performances. He began his career in stage acting in 1963. His first film appearance was in Raja Sannasi (1966).

