INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$M Innas Ali$b$, DATE '1916-09-01', DATE '2010-05-03', $b$M Innas Ali (September 1, 1916 – May 3, 2010) was a Bangladeshi physicist. He was the founding chairman of Bangladesh Atomic Energy Commission. He was selected National Professor of Bangladesh in 1994.

Source: Wikipedia — https://en.wikipedia.org/wiki/M_Innas_Ali$b$, 'en', NULL, $b$Physicist$b$, $b$Netrokona District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abul Hussain$b$, DATE '1922-08-15', DATE '2014-06-29', $b$Abul Hussain (15 August 1922 – 29 June 2014) was a Bangladeshi poet. He was awarded Ekushey Padak in 1980 and Bangla Academy Literary Award in 1963.

