INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Al Mujahidi$b$, DATE '1942-01-01', DATE '2026-06-18', $b$Al Mujahidi (1 January 1943 – 18 June 2026) was a Bangladeshi poet. He was awarded Ekushey Padak in 2003 by the Government of Bangladesh for his contribution to literature.

Source: Wikipedia — https://en.wikipedia.org/wiki/Al_Mujahidi$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Poet%20Al%20Mujahidy.jpg?width=640$b$, $b$Poet$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Enamul Haque$b$, DATE '1943-03-07', DATE '2021-10-11', $b$Enamul Haque, sometimes Enamul Huq (29 May 1943 – 11 October 2021), was a Bangladeshi actor, academician and playwright. He acted in stage, television and film mediums. He was a professor at the Department of Chemistry of Bangladesh University of Engineering and Technology (BUET). He was awarded Ekushey Padak in 2012 by the government of Bangladesh for his contribution to fine arts.

Source: Wikipedia — https://en.wikipedia.org/wiki/Enamul_Haque_(actor)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Enamul%20haque%20%28actor%29%20cropped%20from%20Anisul%20Huq%20speaks%20at%20Indemnity%20discussion%20National%20Press%20Club%20Dhaka%202019-09-26%20%28PID-0036837%29%20%28cropped%29%20%28cropped%29.jpg?width=640$b$, $b$Television actor, Actor$b$, $b$Feni District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Imdad Hossain$b$, NULL, DATE '2011-11-13', $b$Imdad Hossain (c. 1926 – November 13, 2011) was a Bangladeshi artist and language movement activist. He was awarded Ekushey Padak in 2010 by the Government of Bangladesh.

