INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$R. A. Ghani$b$, NULL, DATE '2016-01-15', $b$R. A. Ghani (1927 – 15 January 2016) was a Bangladeshi engineer and Bangladesh Nationalist Party politician. He was a member of the Jatiya Sangsad, and served as the state minister of Science and Technology.

Source: Wikipedia — https://en.wikipedia.org/wiki/R._A._Ghani$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Dr%20R%20A%20Ghani%202008.jpg?width=640$b$, $b$Engineer$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Asaddor Ali$b$, NULL, DATE '2005-04-12', $b$Mohammad Asaddor Ali (Bengali: মুহম্মদ আসাদ্দর আলী) was a Bangladeshi writer, researcher and historian. His research primarily focused on the history of Sylhet. Due to his achievements, he was awarded the Bangla Academy Literary Award in 2004. His research discovered unknown information about Sylheti folk literature, and he wrote 19 books relating to it.

Source: Wikipedia — https://en.wikipedia.org/wiki/Asaddor_Ali$b$, 'en', NULL, $b$Researcher, Writer$b$, NULL, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Sikandar Abu Zafar$b$, DATE '1919-03-19', DATE '1975-07-05', $b$Sikandar Abu Zafar (19 March 1918 – 5 August 1975) was a Bangladeshi journalist, dramatist, writer and poet. Although primarily a poet, he had a smooth stride in various fields of literature. He was always at the forefront of progressive cultural movements. The monthly literary magazine "Samakal", published for a long time under his editorship, became a meeting place for young writers; a strong platform for intellectual protest and resistance against the then Pakistani misrule. This magazine was banned several times and its published issues were confiscated due to its vocal protest against the then Pakistani military rule.

Sikandar Abu Jafar's educational career began at the then Tala BD English High School in Khulna (now Satkhira). After completing his studies there, he studied at Surendranath College (formerly Ripon College) in Kolkata. After completing his education, he joined various intellectual professions from 1941. After the partition, he moved to East Bengal and served as a staff artist of Radio Pakistan until 1953. He was mainly a journalist. He also had experience working in the magazine "Nabojug" edited by Kazi Nazrul Islam. During the Liberation War, he played a major role in editing and publishing the magazine "Saptahik Ovijhan" from Kolkata.

Sikandar Abu Zafar, the author of famous works such as "Amader Sangram Chalbey" and "Bangla Chhado", was also particularly appreciated as a playwright. Apart from "Sirajuddullah", his other famous plays include "Makdsa" (1960), "Shakunta Upakhyan" (1962) and "Mahakabi Alaol" (1966).

Source: Wikipedia — https://en.wikipedia.org/wiki/Sikandar_Abu_Zafar$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Sikandar%20Abu%20Jafar.jpg?width=640$b$, $b$Journalist, Poet, Writer$b$, $b$Satkhira District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Obaidul Huq$b$, DATE '1911-10-31', DATE '2007-10-13', $b$Obaidul Huq (31 October 1911 – 13 October 2007) was a Bangladeshi journalist, cinematographer, playwright and writer.

 He was awarded Ekushey Padak in 1981 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Obaidul_Huq$b$, 'en', NULL, $b$Film director, Journalist, Writer$b$, $b$Feni District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Hamiduzzaman Khan$b$, DATE '1946-03-16', DATE '2025-07-20', $b$Hamiduzzaman Khan (16 March 1946 – 20 July 2025) was a Bangladeshi visual artist and sculptor. He is well known as a sculptor for his theme and form oriented sculptures, in particular sculptures on the theme of Bangladesh War of Liberation and birds. Following the introduction of modernity in sculpture in Bangladesh in the 1950s by Novera Ahmed, Khan was instrumental in the popularization of sculpture in the country through his distinctive form of modernity. Influenced by Alberto Giacometti and Henry Moore, his works manifest expressionism, minimalism, and a constant exploration of purity of material. 

Khan was a painter who, even before becoming known as a sculptor, gained recognition for his watercolour and acrylic paintings in the late 1960s. Zainul Abedin, the founding father of Bangladeshi modern art, acclaimed and encouraged Khan for his watercolours. His watercolours are characterized by abstract expressionism and predominantly on the subjects of natural landscape and human figure.

For his contribution to sculpture, Khan was awarded Ekushey Padak, the second-highest civilian award in Bangladesh, in 2006. In a career spanning over five decades, his works have been exhibited and installed in Bangladesh, South Korea, India, and the United States.

Source: Wikipedia — https://en.wikipedia.org/wiki/Hamiduzzaman_Khan$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Hamiduzzam%20Khan.png?width=640$b$, $b$Sculptor$b$, $b$Kishoreganj District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ataus Samad$b$, DATE '1937-11-16', DATE '2012-09-26', $b$Ataus Samad (16 November 1937 – 26 September 2012) was a Bangladeshi journalist. He was awarded Ekushey Padak in 1992 by the Government of Bangladesh.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ataus_Samad$b$, 'en', NULL, $b$Journalist$b$, $b$Mymensingh District$b$, $b$Dhaka$b$);
