INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Abdul Gafur$b$, DATE '1929-02-19', DATE '2024-09-27', $b$Mohammad Abdul Gafur (19 February 1929 – 27 September 2024) was a Bangladeshi journalist, teacher, writer and language activist of the Bengali language movement that took place in the erstwhile East Pakistan (currently Bangladesh) to make Bengali one of the state languages of Pakistan. He was one of the noted members of Tamaddun Majlish, an Islamic cultural organization which played a vital role at the start of the movement.

In recognition of his contributions to the language movement, he was awarded Ekushey Padak by the Government of Bangladesh in 2005.

Source: Wikipedia — https://en.wikipedia.org/wiki/Abdul_Gafur_(language_activist)$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mohammad%20Abdul%20Gafur.jpg?width=640$b$, $b$Journalist, Teacher$b$, $b$Pangsha Upazila$b$, $b$Dhaka$b$);
