INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Kakon Bibi$b$, NULL, DATE '2018-03-21', $b$Noorjahan Kakon Bibi Bir Protik (Bengali: কাঁকন বিবি, Khasi: Kaket Hanchiata) was a Bangladeshi freedom fighter and secret agent of the Bangladesh Liberation War of 1971. She was arrested and brutally tortured by the Pakistani army. She is one of two female freedom fighters honored with the Bir Protik award in 1996, the fourth highest honor in Bangladesh, due to her gallant contribution in the liberation war.

