INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nazma Anwar$b$, NULL, DATE '2004-12-06', $b$Nazma Anwar (c. 1941 – 14 December 2004) was a Bangladeshi film and television actress, and drama activist. She performed in Bengali films including Hajar Bachhor Dhore (2005), Dukhai (1997) Joyjatra (2004), Shonkhonil Karagar (1992), Chittagong: The Last Stopover (2000), Shankhonad (2004) and also in television drama plays including Iblish, Kothao Keu Nei, and Tahara.

