INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Ahsan Ali$b$, DATE '1937-05-01', DATE '2019-09-10', $b$A. K. Md. Ahsan Ali (known as Ahsan Ali; 1 May 1937 – 10 September 2019) was a Bangladeshi physician. He was notable for the integration of tuberculosis and leprosy with general health services and the introduction of Directly observed treatment, short-course (DOTS) for treatment of tuberculosis and MDT for leprosy. He received the Independence Day Award from the Government of Bangladesh in 2018.

Source: Wikipedia — https://en.wikipedia.org/wiki/Ahsan_Ali_(physician)$b$, 'en', NULL, $b$Physician$b$, $b$Brahmanbaria District$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Qazi Motahar Hossain$b$, DATE '1897-07-30', DATE '1981-10-09', $b$Qazi Motahar Hossain (30 July 1897 – 9 October 1981) was a Bangladeshi writer, scientist, statistician, chess player, and journalist.

Hossain was a pioneer educationalist of Bangladesh. He did original research in statistics and pioneered its education in Bangladesh both as a faculty and administrator. As one of the early faculties of University of Dhaka, he was vigorously active in the cultural circles that grew around it. As a Dhaka-centric literary figure in late British India, a period marked by communality and religious sentiment, Hossain and his literary group Shikha distinguished themselves as proponents of communal harmony and rationalism. He was among the sceptical intellectuals who warned of the consequences of the short-lived state of Pakistan. On several occasions, he vocally criticized Pakistani government policies, most importantly on the state language question.

Source: Wikipedia — https://en.wikipedia.org/wiki/Qazi_Motahar_Hossain$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Kaji%20Motahar%20Hossain.jpg?width=640$b$, $b$Journalist, Physicist, Writer$b$, $b$Kushtia District$b$, $b$Dhaka$b$);
