Source: Wikipedia — https://en.wikipedia.org/wiki/Mrinal_Haque$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/Mrinal%20Haque%20%28cropped%29.jpg?width=640$b$, $b$Sculptor$b$, $b$Rajshahi$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nasreen Pervin Huq$b$, DATE '1958-11-18', DATE '2006-04-24', $b$Nasreen Pervin Huq (Bengali: নাসরীন পারভীন হক; born Bangladesh, 18 November 1958, died Bangladesh, 24 April 2006) was a prominent women's activist and campaigner for women's rights and social justice. 

She died in an accident at her home in Dhaka, when she was crushed by a vehicle. The vehicle was driven by her chauffeur, who was picking her up to go to work as Director of the UK non-governmental organisation Action Aid. Though her death was ruled accidental, some think the driver was paid off by a foreign figure.

Source: Wikipedia — https://en.wikipedia.org/wiki/Nasreen_Pervin_Huq$b$, 'en', $b$https://commons.wikimedia.org/wiki/Special:FilePath/NasreenHuq.jpg?width=640$b$, $b$Activist, Nutritionist$b$, $b$Bangladesh$b$, NULL);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Nilufar Yasmin$b$, DATE '1948-02-13', DATE '2003-03-10', $b$Nilufar Yasmin (13 February 1948 – 10 March 2003) was a Bangladeshi singer of Nazrul Sangeet, Rajanikanta Geeti, Dwijendra Geeti and Atul Prasdi genre. She was the fourth of five Yasmin sisters of Bangladesh music. Her siblings are Farida Yasmin, Fauzia Yasmin, Nazma Yasmin, and Sabina Yasmin. She was awarded Ekushey Padak in 2004 by the Government of Bangladesh. She won Bangladesh National Film Award for Best Female Playback Singer for her performance in the film Shuvoda (1986).

Source: Wikipedia — https://en.wikipedia.org/wiki/Nilufar_Yasmin$b$, 'en', NULL, $b$Singer$b$, $b$Kolkata$b$, $b$Dhaka$b$);
